import { playgroundBuildExplanations } from './playgroundBuildExplanations';

// Step-by-step explanations for Coding Challenge templates.
// Loaded lazily from CodePlayground only when the user opens the explanation
// modal — keeps this off the initial route chunk.
//
// Data model is intentionally narrow: the modal renders a few primitive
// "snapshot" views (array, hash map, pseudocode) and walks through `steps`
// frame-by-frame. Adding a new explanation means filling out the same shape
// for whatever data structures the algorithm uses.

export type Highlight = 'i' | 'j' | 'hit' | 'new' | 'compare' | 'found';

export interface ArrayCell {
  value: string | number;
  highlight?: Highlight;
}

export interface ArraySnapshot {
  cells: ArrayCell[];
  pointers?: { index: number; label: string; color: 'red' | 'amber' | 'emerald' | 'indigo' }[];
}

export interface MapEntry {
  key: string | number;
  value: string | number;
  highlight?: 'new' | 'hit';
}

export interface MapSnapshot {
  entries: MapEntry[];
}

// ===== Extra snapshot primitives for non-iterative algorithms =====

export interface StackSnapshot {
  // First item is the BOTTOM of the stack, last is the TOP.
  items: ArrayCell[];
  // What's happening this step at the top of the stack.
  action?: 'push' | 'pop' | 'peek' | 'idle';
}

export interface SetSnapshot {
  items: { value: string | number; highlight?: 'new' | 'hit' }[];
}

// Two arrays side by side — useful for merge / compare visualizations.
export interface DualArraySnapshot {
  left: { label: string; cells: ArrayCell[]; pointer?: number };
  right: { label: string; cells: ArrayCell[]; pointer?: number };
  result?: { label: string; cells: ArrayCell[] };
}

// Function call frames for recursion (top is most recent).
export interface CallStackSnapshot {
  frames: { call: string; status?: 'active' | 'returned' | 'pending'; returns?: string }[];
}

// Linked-list nodes drawn left-to-right with → arrows.
export interface LinkedListSnapshot {
  nodes: { value: string | number; highlight?: Highlight; label?: string }[];
  // Optional next pointer label between nodes ("null" or other).
  tail?: string;
}

// Horizontal timeline — for debounce/throttle/event-loop kinds of problems.
export interface TimelineSnapshot {
  events: { t: number; label: string; kind: 'input' | 'fire' | 'skip' | 'pending' }[];
  windowMs?: number;
}

export interface ExplanationStep {
  // One-sentence summary that appears below the visual.
  title: string;
  // Optional longer paragraph for the "Why?" panel.
  detail?: string;
  // Highlighted pseudocode line index (0-based into approach.pseudocode).
  pseudoLine?: number;
  // Visual frames — render whichever ones are present.
  array?: ArraySnapshot;
  map?: MapSnapshot;
  stack?: StackSnapshot;
  set?: SetSnapshot;
  dualArray?: DualArraySnapshot;
  callStack?: CallStackSnapshot;
  linkedList?: LinkedListSnapshot;
  timeline?: TimelineSnapshot;
  // The math/comparison being performed this step (e.g., "9 - 2 = 7").
  computation?: { label: string; lhs?: string; op?: string; rhs?: string; result?: string };
  // Inline lookup outcome: 'hit' (found) / 'miss' (not found) / undefined.
  lookupOutcome?: { kind: 'hit' | 'miss'; key: string | number; at?: string };
  // Free-form note rendered as a soft callout.
  note?: string;
  // Final output once the algorithm decides.
  result?: { found: true; value: string } | { found: false; value?: string };
}

// Reference to a polyfill template that this approach leans on. The modal
// renders these as clickable chips — clicking loads that polyfill template
// in the playground so the user can see how the built-in works under the
// hood.
export interface PolyfillRef {
  /** Built-in name, e.g. "Array.prototype.reduce" */
  builtin: string;
  /** Matches a `name` in playgroundTemplates.ts JS Polyfills category */
  templateName: string;
  /** Optional one-liner explaining how this approach uses the built-in */
  why?: string;
}

export interface Approach {
  id: string;
  name: string;
  badge: 'best' | 'baseline' | 'alternative';
  intuition: string;
  complexity: { time: string; space: string; verdict: string };
  pseudocode: string[];
  example: { input: string; output: string };
  steps: ExplanationStep[];
  tradeoffs: string;
  /** Built-ins this approach uses that have a polyfill template in the playground */
  usesPolyfills?: PolyfillRef[];
  /** Optional side-by-side comparison blocks. When present, the modal renders
   *  the primary pseudocode + each compare block as columns. Useful for
   *  paired algorithms like rotate-left vs rotate-right. The primary's
   *  pseudoLine highlight applies only to the primary column. */
  pseudocodeCompare?: { label: string; lines: string[]; highlightLine?: number }[];
  /** Optional label for the primary pseudocode when shown alongside compare blocks. */
  pseudocodeLabel?: string;
}

export interface Explanation {
  problem: string;
  problemStatement: string;
  approaches: Approach[];
}

// ===================================================================
// Build-order explanations — for React machine-coding templates.
//
// The `Approach`/`steps` model above is algorithm-shaped: it wants a Big-O row,
// pseudocode, and a data structure to walk frame by frame. A machine-coding
// template has none of those — no array to step through, no complexity to
// compare — which is why all 36 React templates shipped with no Explain button
// at all, and their teaching content stayed as a wall of comments in the editor.
//
// What a reader needs there is the order you would build it in, the one
// decision each stage encodes, and the trap that stage hides.
// ===================================================================

export interface BuildStep {
  /** Imperative, e.g. "Tell the browser how wide it will display". */
  title: string;
  /** Why this step exists and what decision it encodes. */
  detail: string;
  /**
   * Locates the excerpt IN THE TEMPLATE, rather than restating it.
   *
   * The first version of these walkthroughs carried hand-written `code`
   * strings, and 360 of 454 lines turned out not to exist in the template the
   * reader had open — they described an idealised implementation instead of the
   * one on screen, which is worse than no snippet at all. An anchor cannot
   * drift: the modal slices the real lines out of the real template, and
   * `buildExplanationAnchors.test.ts` fails the build if `from` stops matching.
   */
  excerpt?: {
    /** A distinctive substring of the first line to show. Must be unique-ish. */
    from: string;
    /** How many lines to show from there. Default 6. */
    lines?: number;
  };
  /** The mistake this step prevents. Rendered as a warning callout. */
  pitfall?: string;
}

export interface GradedPoint {
  point: string;
  why: string;
}

export interface BuildExplanation {
  kind: 'build';
  problem: string;
  /** THE BRIEF — what you are asked to produce, in 1-3 sentences. */
  problemStatement: string;
  buildOrder: BuildStep[];
  graded: GradedPoint[];
}

export type AnyExplanation = Explanation | BuildExplanation;

// The `isBuildExplanation` guard deliberately lives in ./explanationKind.ts —
// importing it from here would make every caller a static consumer of this
// 10,600-line module, which is the whole thing the lazy import avoids.

// ====================================================================

const twoSum: Explanation = {
  problem: 'Two Sum',
  problemStatement:
    'Given an array of integers `nums` and a target integer `target`, return the indices of the two numbers that add up to target. Each input has exactly one solution and the same element may not be used twice.',
  approaches: [
    // --------------------------- BRUTE FORCE ---------------------------
    {
      id: 'brute-force',
      name: 'Brute Force — Nested Loops',
      badge: 'baseline',
      intuition:
        "**Try every pair.** Fix a first index i, then pair it with every later index j and check whether the two numbers add up to the target.\n\n" +
        "• nums[i] + nums[j] === target: return [i, j].\n" +
        "• Otherwise move j right. When j runs off the end, move i right and start j again just after it.\n\n" +
        "Starting j at i + 1 (not 0) means each pair is checked once and no element is paired with itself. It is guaranteed correct, but it does up to n·(n−1)/2 checks.",
      complexity: { time: 'O(n²)', space: 'O(1)', verdict: 'Don\'t ship — too slow on large inputs' },
      pseudocode: [
        'for i from 0 to n-1:',
        '  for j from i+1 to n-1:',
        '    if nums[i] + nums[j] === target:',
        '      return [i, j]',
        'return [] // no solution',
      ],
      example: { input: 'nums = [3, 2, 4], target = 6', output: '[1, 2]' },
      steps: [
        {
          title: 'Start with i = 0. nums[0] = 3 will be paired with every j after it.',
          pseudoLine: 0,
          array: {
            cells: [
              { value: 3, highlight: 'i' },
              { value: 2 },
              { value: 4 },
            ],
            pointers: [{ index: 0, label: 'i', color: 'red' }],
          },
        },
        {
          title: 'i=0, j=1. Check 3 + 2.',
          detail: '3 + 2 = 5, which is not equal to target 6. Move j forward.',
          pseudoLine: 2,
          array: {
            cells: [
              { value: 3, highlight: 'i' },
              { value: 2, highlight: 'j' },
              { value: 4 },
            ],
            pointers: [
              { index: 0, label: 'i', color: 'red' },
              { index: 1, label: 'j', color: 'amber' },
            ],
          },
          computation: { label: 'nums[i] + nums[j] vs target', lhs: '3', op: '+', rhs: '2', result: '5 ≠ 6' },
        },
        {
          title: 'i=0, j=2. Check 3 + 4.',
          detail: '3 + 4 = 7, also not 6. j has run off the end, so move i forward.',
          pseudoLine: 2,
          array: {
            cells: [
              { value: 3, highlight: 'i' },
              { value: 2 },
              { value: 4, highlight: 'j' },
            ],
            pointers: [
              { index: 0, label: 'i', color: 'red' },
              { index: 2, label: 'j', color: 'amber' },
            ],
          },
          computation: { label: 'nums[i] + nums[j] vs target', lhs: '3', op: '+', rhs: '4', result: '7 ≠ 6' },
        },
        {
          title: 'i=1, j=2. Check 2 + 4.',
          detail: '2 + 4 = 6 — match! Return [1, 2].',
          pseudoLine: 3,
          array: {
            cells: [
              { value: 3 },
              { value: 2, highlight: 'i' },
              { value: 4, highlight: 'found' },
            ],
            pointers: [
              { index: 1, label: 'i', color: 'red' },
              { index: 2, label: 'j', color: 'emerald' },
            ],
          },
          computation: { label: 'nums[i] + nums[j] vs target', lhs: '2', op: '+', rhs: '4', result: '6 = 6 ✓' },
          result: { found: true, value: '[1, 2]' },
        },
      ],
      tradeoffs:
        "Pick this only if n is tiny (say, ≤ 100) or if you need a baseline you're certain is correct. For typical interview inputs (n up to 10,000+), nested loops will time out — recruiters expect you to recognize this and switch.",
    },
    // ----------------------------- HASH MAP -----------------------------
    {
      id: 'hash-map',
      name: 'Hash Map — One Pass',
      badge: 'best',
      intuition:
        "**Remember what you have seen, so each number only has to look back once.** For each number, the partner it needs is the complement, meaning target − nums[i]. A hash map (a key → value table with O(1) lookups) stores every number seen so far → its index.\n\n" +
        "• Complement is in the map: the pair is [map[complement], i]. Return it.\n" +
        "• Otherwise store nums[i] → i and move on.\n\n" +
        "**Why looking back is enough:** when the second number of the pair is reached, the first one is already in the map. Storing *after* the lookup is what stops a number from pairing with itself (target 6, nums[i] = 3).",
      complexity: { time: 'O(n)', space: 'O(n)', verdict: 'Ship this — the canonical answer' },
      pseudocode: [
        'map = {}',
        'for i from 0 to n-1:',
        '  complement = target - nums[i]',
        '  if complement in map:',
        '    return [map[complement], i]',
        '  map[nums[i]] = i',
        'return [] // no solution',
      ],
      example: { input: 'nums = [2, 7, 11, 15], target = 9', output: '[0, 1]' },
      steps: [
        {
          title: 'Start with an empty map.',
          detail: 'The map will store numbers we have already seen, mapped to their index.',
          pseudoLine: 0,
          array: {
            cells: [
              { value: 2 },
              { value: 7 },
              { value: 11 },
              { value: 15 },
            ],
          },
          map: { entries: [] },
        },
        {
          title: 'i = 0, nums[i] = 2. Compute complement = 9 − 2 = 7.',
          detail: 'We need to find a 7 somewhere. Check the map.',
          pseudoLine: 2,
          array: {
            cells: [
              { value: 2, highlight: 'i' },
              { value: 7 },
              { value: 11 },
              { value: 15 },
            ],
            pointers: [{ index: 0, label: 'i', color: 'indigo' }],
          },
          map: { entries: [] },
          computation: { label: 'complement = target − nums[i]', lhs: '9', op: '−', rhs: '2', result: '7' },
        },
        {
          title: 'Is 7 in the map? No — map is empty.',
          detail: "Store the current number 2 → its index 0 in the map. Then move on to i = 1.",
          pseudoLine: 5,
          array: {
            cells: [
              { value: 2, highlight: 'i' },
              { value: 7 },
              { value: 11 },
              { value: 15 },
            ],
            pointers: [{ index: 0, label: 'i', color: 'indigo' }],
          },
          map: { entries: [{ key: 2, value: 0, highlight: 'new' }] },
          lookupOutcome: { kind: 'miss', key: 7 },
        },
        {
          title: 'i = 1, nums[i] = 7. Compute complement = 9 − 7 = 2.',
          detail: 'We need to find a 2. Check the map.',
          pseudoLine: 2,
          array: {
            cells: [
              { value: 2 },
              { value: 7, highlight: 'i' },
              { value: 11 },
              { value: 15 },
            ],
            pointers: [{ index: 1, label: 'i', color: 'indigo' }],
          },
          map: { entries: [{ key: 2, value: 0 }] },
          computation: { label: 'complement = target − nums[i]', lhs: '9', op: '−', rhs: '7', result: '2' },
        },
        {
          title: 'Is 2 in the map? YES — at index 0.',
          detail: 'Return [map[2], i] = [0, 1]. Done in one pass with two lookups.',
          pseudoLine: 4,
          array: {
            cells: [
              { value: 2, highlight: 'found' },
              { value: 7, highlight: 'found' },
              { value: 11 },
              { value: 15 },
            ],
            pointers: [{ index: 1, label: 'i', color: 'emerald' }],
          },
          map: { entries: [{ key: 2, value: 0, highlight: 'hit' }] },
          lookupOutcome: { kind: 'hit', key: 2, at: '0' },
          result: { found: true, value: '[0, 1]' },
        },
      ],
      tradeoffs:
        "Trades O(n) extra space for O(n) time. Always the right answer in interviews unless the interviewer explicitly bans extra space (in which case fall back to sorting + two pointers — but that needs O(n log n) and loses the original indices unless you keep them paired).",
    },
  ],
};

// ====================================================================

// One Reverse String frame: the character buffer with the L / R pointers.
// `swapped` marks the two cells that were just exchanged.
const reverseStringFrame = (chars: string, l: number, r: number, swapped = false): ArraySnapshot => ({
  cells: chars.split('').map((c, idx) => ({
    value: c,
    highlight: swapped && (idx === l || idx === r) ? 'new' as const
      : idx === l ? 'i' as const : idx === r ? 'j' as const : undefined,
  })),
  pointers: l === r
    ? [{ index: l, label: 'L=R', color: 'emerald' as const }]
    : [{ index: l, label: 'L', color: 'red' as const }, { index: r, label: 'R', color: 'amber' as const }],
});

const reverseString: Explanation = {
  problem: 'Reverse String',
  problemStatement: 'Reverse a string with no use of the built-in reverse. The interviewer is looking for the two-pointer pattern; the one-liner with split/reverse/join is acceptable in real code but in interviews you should articulate what those built-ins do internally.',
  approaches: [{
    id: 'two-pointer',
    name: 'Two-Pointer Swap (Best)',
    badge: 'best',
    intuition:
      "**Swap the two ends, then move inward.** Position 0 must end up holding the last character, position 1 the second-to-last, and so on, so each mirror pair is swapped exactly once.\n\n" +
      "**Step 1: copy into an array.** JavaScript strings are immutable (they cannot be changed in place), so `s[0] = \"x\"` silently does nothing. split(\"\") gives a buffer you can swap in.\n\n" +
      "**Step 2: two pointers.** L starts at index 0 and R at the last index. While L < R:\n" +
      "• swap arr[L] and arr[R]\n" +
      "• move L one right and R one left\n\n" +
      "The loop stops when the pointers meet (odd length) or cross (even length). A middle character of an odd-length string never moves, because it is already in its final spot. That is n/2 swaps, so O(n).",
    complexity: { time: 'O(n)', space: 'O(n) for the array intermediate; O(1) extra beyond that', verdict: 'Ship this — what interviewers expect' },
    pseudocode: [
      'arr = str.split("")              // immutable string → mutable array',
      'left = 0, right = arr.length - 1',
      'while left < right:',
      '  swap arr[left] with arr[right] // [arr[left], arr[right]] = [arr[right], arr[left]]',
      '  left++, right--',
      'return arr.join("")              // array back to string',
    ],
    example: { input: '"hello"', output: '"olleh"' },
    steps: [
      { title: 'Split "hello" into a 5-cell array. L = 0, R = 4.', pseudoLine: 1,
        detail: 'The array is a mutable copy. The original string is never touched.',
        array: reverseStringFrame('hello', 0, 4) },
      { title: 'L=0, R=4: 0 < 4, so swap "h" ↔ "o" → "oellh". Then L = 1, R = 3.', pseudoLine: 3,
        detail: 'The destructuring swap [a[i], a[j]] = [a[j], a[i]] needs no temp variable, but it is still three moves underneath: temp = a[i]; a[i] = a[j]; a[j] = temp.',
        array: reverseStringFrame('oellh', 0, 4, true),
        computation: { label: 'swap arr[0] ↔ arr[4]', lhs: '"h" ↔ "o"', result: '"oellh"' } },
      { title: 'L=1, R=3: 1 < 3, so swap "e" ↔ "l" → "olleh". Then L = 2, R = 2.', pseudoLine: 3,
        array: reverseStringFrame('olleh', 1, 3, true),
        computation: { label: 'swap arr[1] ↔ arr[3]', lhs: '"e" ↔ "l"', result: '"olleh"' } },
      { title: 'L=2, R=2: 2 < 2 is false, so the loop stops. The middle "l" never moves.', pseudoLine: 2,
        detail: 'Swapping a cell with itself would change nothing, which is why the condition is < and not <=.',
        array: reverseStringFrame('olleh', 2, 2),
        computation: { label: 'left < right', lhs: '2 < 2', result: 'false → exit loop' } },
      { title: 'Join the array back into a string and return "olleh".', pseudoLine: 5,
        array: { cells: 'olleh'.split('').map(c => ({ value: c, highlight: 'found' as const })) },
        result: { found: true, value: '"olleh"' } },
    ],
    tradeoffs: "This is the answer the interviewer wants — it shows you understand the two-pointer pattern, can manipulate indices, and recognize that strings are immutable. The split-reverse-join one-liner is essentially this same algorithm wrapped behind built-ins (V8's `reverse` is in fact a two-pointer swap loop in C++).",
  },
  {
    id: 'split-reverse-join',
    name: 'Built-in Chain — split → reverse → join (Alternative)',
    badge: 'alternative',
    intuition:
      "**Three built-ins, each doing one job:** `str.split('').reverse().join('')`. Fine in production code, but usually rejected in interviews because it hides the algorithm, so be ready to say what each call does.\n\n" +
      "• `split('')` turns the string into an array of single characters: O(n) time and space.\n" +
      "• `Array.prototype.reverse()` runs the same two-pointer swap loop as Approach 1, inside the engine.\n" +
      "• `join('')` walks the array and concatenates the characters back into a string: O(n).\n\n" +
      "So the one-liner is three O(n) passes, about 3× the work of the hand-rolled loop, and still O(n) overall.",
    complexity: { time: 'O(n) but with a 3× constant factor', space: 'O(n)', verdict: 'Real-world: fine. Interview: explain what the built-ins do, then offer the two-pointer.' },
    pseudocode: [
      'return str.split("").reverse().join("")',
      '// equivalent to:',
      '// arr = str.split("")     ← O(n)',
      '// arr.reverse()           ← O(n) two-pointer swap',
      '// return arr.join("")     ← O(n)',
    ],
    example: { input: '"hello"', output: '"olleh"' },
    steps: [
      { title: 'split("") turns "hello" into ["h", "e", "l", "l", "o"].', pseudoLine: 2,
        detail: 'split with an empty separator yields one entry per UTF-16 code unit, so an emoji (two code units) is broken into halves. Array.from(str) splits by code point instead.',
        array: { cells: 'hello'.split('').map(c => ({ value: c })) } },
      { title: 'reverse(), swap 1 inside the engine: index 0 ↔ 4 → ["o", "e", "l", "l", "h"].', pseudoLine: 3,
        array: reverseStringFrame('oellh', 0, 4, true) },
      { title: 'reverse(), swap 2: index 1 ↔ 3 → ["o", "l", "l", "e", "h"]. Both indices are now 2, so reverse() stops.', pseudoLine: 3,
        array: reverseStringFrame('olleh', 1, 3, true) },
      { title: 'join("") concatenates the cells with no separator → "olleh".', pseudoLine: 4,
        array: { cells: 'olleh'.split('').map(c => ({ value: c, highlight: 'found' as const })) },
        result: { found: true, value: '"olleh"' } },
    ],
    tradeoffs: "Use this one-liner in everyday code. In an interview, expect a follow-up: 'now do it without reverse'. That's your cue to switch to two-pointer.",
    usesPolyfills: [
      { builtin: 'Array.prototype.reverse', templateName: 'Array.reverse',
        why: 'reverse() is the two-pointer swap loop wrapped in a built-in' },
      { builtin: 'Array.prototype.join', templateName: 'Array.prototype.join',
        why: 'join concatenates the reversed character array back to a string' },
    ],
  }],
};

// ====================================================================

// One Valid Palindrome frame over "Race, car" (a space is drawn as ␣).
const VALID_PALINDROME_INPUT = 'Race, car';
const validPalindromeFrame = (l: number, r: number, done = false): ArraySnapshot => ({
  cells: VALID_PALINDROME_INPUT.split('').map((c, idx) => ({
    value: c === ' ' ? '␣' : c,
    highlight: done ? undefined : idx === l ? 'i' as const : idx === r ? 'j' as const : undefined,
  })),
  pointers: l === r
    ? [{ index: l, label: 'L=R', color: 'emerald' as const }]
    : [{ index: l, label: 'L', color: 'red' as const }, { index: r, label: 'R', color: 'amber' as const }],
});

const validPalindrome: Explanation = {
  problem: 'Valid Palindrome',
  problemStatement: 'Determine if a string reads the same forwards and backwards, ignoring case and non-alphanumeric characters. Punctuation, spaces, and case differences should NOT cause a false negative — `"A man, a plan, a canal: Panama"` is a palindrome.',
  approaches: [{
    id: 'two-pointer',
    name: 'Two-Pointer Compare (Best — O(1) space)',
    badge: 'best',
    intuition:
      "**Compare the outside pair, then move inward.** A palindrome reads the same both ways, so the first letter must equal the last, the second must equal the second-to-last, and so on. L starts at the left end and R at the right end.\n\n" +
      "Each round of the loop:\n" +
      "• Skip: move L right past any character that is not alphanumeric (a letter or digit), and move R left the same way. Spaces and punctuation never get compared.\n" +
      "• Compare the two characters lowercased. Different → return false.\n" +
      "• Same → move both pointers one step inward.\n" +
      "When L and R meet or cross, every pair matched, so return true.\n\n" +
      "**Why it is still O(n):** the skip loops look nested, but each character is passed over at most once in total (by L or by R), and nothing is copied, so the extra space is O(1).",
    complexity: { time: 'O(n)', space: 'O(1)', verdict: 'Best — no allocation' },
    pseudocode: [
      'left = 0, right = s.length - 1',
      'while left < right:',
      '  while left<right and !isAlnum(s[left]):  left++   // skip non-alnum on left',
      '  while left<right and !isAlnum(s[right]): right--  // skip non-alnum on right',
      '  if lower(s[left]) !== lower(s[right]): return false',
      '  left++, right--',
      'return true',
    ],
    example: { input: '"Race, car"', output: 'true' },
    steps: [
      { title: 'L = 0 at "R", R = 8 at "r".', pseudoLine: 0,
        detail: 'The comma and the space in the middle are the characters the skip loops exist for.',
        array: validPalindromeFrame(0, 8) },
      { title: 'L=0, R=8: both are letters, and "R" lowercased equals "r" → match. L = 1, R = 7.', pseudoLine: 4,
        detail: 'Lowercasing both sides is what makes "R" and "r" count as the same character.',
        array: validPalindromeFrame(0, 8),
        computation: { label: 'lower(s[L]) === lower(s[R])', lhs: '"r" === "r"', result: 'true → step inward' } },
      { title: 'L=1, R=7: "a" equals "a" → match. L = 2, R = 6.', pseudoLine: 4,
        array: validPalindromeFrame(1, 7),
        computation: { label: 'lower(s[L]) === lower(s[R])', lhs: '"a" === "a"', result: 'true → step inward' } },
      { title: 'L=2, R=6: "c" equals "c" → match. L = 3, R = 5.', pseudoLine: 4,
        array: validPalindromeFrame(2, 6),
        computation: { label: 'lower(s[L]) === lower(s[R])', lhs: '"c" === "c"', result: 'true → step inward' } },
      { title: 'L=3, R=5: s[5] is a space, not alphanumeric → R-- to 4.', pseudoLine: 3,
        detail: 's[3] = "e" is a letter, so the left skip loop did nothing this round.',
        array: validPalindromeFrame(3, 5),
        computation: { label: 'isAlnum(s[5])', lhs: 'isAlnum(" ")', result: 'false → right--' } },
      { title: 'L=3, R=4: s[4] is ",", not alphanumeric → R-- to 3. Now L = R, so the skip loop stops.', pseudoLine: 3,
        detail: 'The left<right guard inside the skip loop is what stops R from running past L.',
        array: validPalindromeFrame(3, 4),
        computation: { label: 'isAlnum(s[4])', lhs: 'isAlnum(",")', result: 'false → right--' } },
      { title: 'L=3, R=3: "e" is compared with itself → match. L = 4, R = 2.', pseudoLine: 4,
        array: validPalindromeFrame(3, 3),
        computation: { label: 'lower(s[L]) === lower(s[R])', lhs: '"e" === "e"', result: 'true → step inward' } },
      { title: 'L=4 > R=2, so the outer loop ends. No pair differed → return true.', pseudoLine: 6,
        detail: 'Four letter pairs were compared (R/r, a/a, c/c, e/e); the comma and the space were never compared.',
        array: validPalindromeFrame(4, 2, true),
        result: { found: true, value: 'true' } },
    ],
    tradeoffs: "This is the canonical answer. It is harder to write correctly (off-by-one in the inner skip-loops is the classic bug — be careful with the `left<right` guard) but interviewers want to see you handle the 'ignore certain chars' rule without allocating a new string.",
  },
  {
    id: 'regex-strip',
    name: 'Strip with Regex + Compare Reversed (Alternative — readable)',
    badge: 'alternative',
    intuition:
      "Build a clean version of the string — only alphanumeric, lowercased — then check if it equals its own reverse. Less code, easier to reason about, easier to extend (e.g., 'also ignore underscores' is a single character class change). The cost is O(n) extra space for the cleaned copy.\n\n" +
      "**The regex `/[^a-z0-9]/gi` is the centerpiece. Let's break it down piece by piece:**\n\n" +
      "• `[ ]` — a *character class*, meaning 'any one character from this set'.\n" +
      "• `^` (only when it's the first thing inside `[]`) — *negation*. Now the class means 'any character NOT in this set'.\n" +
      "• `a-z` — a range: lowercase letters a through z.\n" +
      "• `0-9` — another range: digits.\n" +
      "• `g` flag (after the closing `/`) — *global*: replace ALL occurrences, not just the first.\n" +
      "• `i` flag — *case-insensitive*: `a-z` also matches `A-Z` because of `i`. (Without `i` we would write `[^a-zA-Z0-9]` instead.)\n\n" +
      "So the whole pattern reads: 'every character that is not a lowercase letter, not an uppercase letter (because of `i`), and not a digit'. We hand it to `replace(re, '')` to delete each such character. After that, we lowercase what remains and compare with its reverse.",
    complexity: { time: 'O(n)', space: 'O(n)', verdict: 'Use when readability matters more than the constant-factor space savings' },
    pseudocode: [
      'cleaned = s.replace(/[^a-z0-9]/gi, "").toLowerCase()',
      'reversed = cleaned.split("").reverse().join("")',
      'return cleaned === reversed',
    ],
    example: { input: '"A man, a plan, a canal: Panama"', output: 'true' },
    steps: [
      {
        title: 'Strip non-alphanumeric. "A man, a plan, a canal: Panama" → "AmanaplanacanalPanama".',
        detail: 'The regex `/[^a-z0-9]/gi` matches every space, comma, colon. The `g` flag means replace ALL occurrences. The `i` flag means a-z also matches A-Z, so we keep both cases in this step.',
        pseudoLine: 0,
        note: '**The regex breakdown:** `[^a-z0-9]` = any one char NOT in (lowercase letters | digits). The `i` flag extends this to uppercase letters too. The `g` flag triggers global replace.',
        computation: { label: 'replace(/[^a-z0-9]/gi, "")', lhs: '"A man, a plan, a canal: Panama"', op: '→', rhs: '"AmanaplanacanalPanama"' },
      },
      {
        title: 'Lowercase it: "amanaplanacanalpanama".',
        pseudoLine: 0,
        computation: { label: 'toLowerCase()', lhs: '"AmanaplanacanalPanama"', result: '"amanaplanacanalpanama"' },
      },
      {
        title: 'Reverse: split → reverse → join → "amanaplanacanalpanama".',
        detail: 'It happens to be the same forward and backward (that is what palindrome means).',
        pseudoLine: 1,
        computation: { label: 'split→reverse→join', lhs: '"amanaplanacanalpanama"', result: '"amanaplanacanalpanama"' },
      },
      {
        title: 'Compare. cleaned === reversed → return true.',
        pseudoLine: 2,
        computation: { label: 'strict equality', lhs: 'cleaned === reversed', result: 'true' },
        result: { found: true, value: 'true' },
      },
    ],
    tradeoffs: "Three passes over the string (replace, toLowerCase, reverse) plus the equality check — about 4× the work of the two-pointer approach, plus O(n) memory. Real-world: this is fine; the readability is worth it. Interview: be ready for 'now do it in O(1) space' which is the cue to switch to two-pointer.",
    usesPolyfills: [
      { builtin: 'Array.prototype.reverse', templateName: 'Array.reverse',
        why: 'reverse the cleaned character array to compare against the original' },
    ],
  }],
};

