// FizzBuzz traces are generated by running the rule on each i, so the
// titles and cells can never disagree with the algorithm. Cells abbreviate
// "FizzBuzz" to "FzBz" to fit the 4-character cell.
const fizzBuzzWord = (i: number): string =>
  i % 15 === 0 ? 'FizzBuzz' : i % 3 === 0 ? 'Fizz' : i % 5 === 0 ? 'Buzz' : String(i);
const fizzBuzzOutputFrame = (upTo: number, done = false): ArraySnapshot => ({
  cells: Array.from({ length: upTo }, (_, k) => {
    const w = fizzBuzzWord(k + 1);
    return {
      value: w === 'FizzBuzz' ? 'FzBz' : w,
      highlight: done ? 'found' as const : k + 1 === upTo ? 'new' as const : undefined,
    };
  }),
});
const FIZZ_BUZZ_OUTPUT = '[1,2,Fizz,4,Buzz,Fizz,7,8,Fizz,Buzz,11,Fizz,13,14,FizzBuzz]';
const fizzBuzzModuloStep = (i: number): ExplanationStep => {
  const w = fizzBuzzWord(i);
  const line = i % 15 === 0 ? 1 : i % 3 === 0 ? 2 : i % 5 === 0 ? 3 : 4;
  const why = i % 15 === 0 ? `${i} % 15 = 0`
    : i % 3 === 0 ? `${i} % 15 = ${i % 15}, ${i} % 3 = 0`
    : i % 5 === 0 ? `${i} % 15 = ${i % 15}, ${i} % 3 = ${i % 3}, ${i} % 5 = 0`
    : `${i} % 15, % 3 and % 5 are all non-zero`;
  return {
    title: `i=${i}: ${why} → push "${w}".`,
    pseudoLine: line,
    ...(i === 15 ? { detail: '15 is a multiple of 3 as well, so if the % 3 branch came first it would push "Fizz" and never reach this case. Most specific check first.' } : {}),
    array: fizzBuzzOutputFrame(i, i === 15),
    computation: { label: 'i % 15, i % 3, i % 5', lhs: `${i % 15}, ${i % 3}, ${i % 5}`, result: `"${w}"` },
    ...(i === 15 ? { result: { found: true as const, value: FIZZ_BUZZ_OUTPUT } } : {}),
  };
};
const fizzBuzzConcatStep = (i: number): ExplanationStep => {
  const s = (i % 3 === 0 ? 'Fizz' : '') + (i % 5 === 0 ? 'Buzz' : '');
  const line = s === '' ? 4 : i % 5 === 0 ? 3 : 2;
  const fizz = i % 3 === 0 ? `${i} % 3 = 0 → s = "Fizz"` : `${i} % 3 = ${i % 3}`;
  const buzz = i % 5 === 0 ? `${i} % 5 = 0 → s += "Buzz"` : `${i} % 5 = ${i % 5}`;
  return {
    title: `i=${i}: ${fizz}; ${buzz}. Push "${s || String(i)}".`,
    pseudoLine: line,
    ...(i === 1 ? { detail: 'Neither rule fired, so s is still "". An empty string is falsy, so s || String(i) falls through to "1".' } : {}),
    ...(i === 15 ? { detail: 'Both rules fired and their words concatenated. No "multiple of 15" branch was needed.' } : {}),
    array: fizzBuzzOutputFrame(i, i === 15),
    computation: { label: 's || String(i)', lhs: `"${s}" || "${i}"`, result: `"${s || String(i)}"` },
    ...(i === 15 ? { result: { found: true as const, value: FIZZ_BUZZ_OUTPUT } } : {}),
  };
};
const FIZZ_BUZZ_IS = Array.from({ length: 15 }, (_, k) => k + 1);

const fizzBuzz: Explanation = {
  problem: 'FizzBuzz',
  problemStatement: 'For numbers 1..n: print "Fizz" for multiples of 3, "Buzz" for multiples of 5, "FizzBuzz" for multiples of 15 (which are multiples of both), otherwise the number itself. The classic screening question — designed to filter out candidates who cannot translate plain-English rules into code.',
  approaches: [{
    id: 'modulo',
    name: 'Modulo Branching (Best)',
    badge: 'best',
    intuition:
      "**Loop from 1 to n and pick one word per number.** `i % k` (modulo, the remainder after dividing i by k) is 0 exactly when i is a multiple of k. Check in this order:\n" +
      "• i % 15 === 0 → \"FizzBuzz\"\n" +
      "• else i % 3 === 0 → \"Fizz\"\n" +
      "• else i % 5 === 0 → \"Buzz\"\n" +
      "• else the number itself, as a string\n\n" +
      "**The one trap is the order.** A multiple of 15 is also a multiple of 3, and in an if / else if chain the first true branch wins. Put % 3 first and 15 prints \"Fizz\". So the most specific case goes first. Each number costs O(1), so the loop is O(n).",
    complexity: { time: 'O(n)', space: 'O(n) for the output array; O(1) extra', verdict: 'Canonical — what every interviewer expects' },
    pseudocode: [
      'for i from 1 to n:',
      '  if i % 15 === 0: push "FizzBuzz"',
      '  else if i % 3 === 0: push "Fizz"',
      '  else if i % 5 === 0: push "Buzz"',
      '  else: push String(i)',
    ],
    example: { input: 'n = 15', output: FIZZ_BUZZ_OUTPUT },
    steps: FIZZ_BUZZ_IS.map(fizzBuzzModuloStep),
    tradeoffs: "A 'string-build' variant concatenates: `s = (i%3?'':'Fizz') + (i%5?'':'Buzz') || String(i)`. Same output, slightly slower in tight loops, more readable to some. Lookup-table variants exist but rarely win on n ≤ 10⁶.",
  },
  {
    id: 'string-concat',
    name: 'String Concatenation — No Branching (Alternative)',
    badge: 'alternative',
    intuition:
      "**Build the word from parts instead of choosing it.** Start each number with an empty string s:\n" +
      "• i % 3 === 0 → append \"Fizz\"\n" +
      "• i % 5 === 0 → append \"Buzz\"\n" +
      "• push `s || String(i)`\n\n" +
      "**Why the multiple-of-15 case disappears:** 15 passes both checks, so s becomes \"Fizz\" + \"Buzz\" on its own. And `s || String(i)` works because an empty string is falsy, so when neither rule fired, || falls through to the number. Adding \"Bazz for multiples of 7\" is one more line, with no reordering.",
    complexity: { time: 'O(n)', space: 'O(n)', verdict: 'Cleaner for extending; slightly slower per iteration' },
    pseudocode: [
      'for i from 1 to n:',
      '  s = ""',
      '  if i % 3 === 0: s += "Fizz"',
      '  if i % 5 === 0: s += "Buzz"',
      '  push(s || String(i))',
    ],
    example: { input: 'n = 15', output: FIZZ_BUZZ_OUTPUT },
    steps: FIZZ_BUZZ_IS.map(fizzBuzzConcatStep),
    tradeoffs: "Slightly slower in microbenchmarks (string concat allocates) but more elegant when the rules grow (Fizz/Buzz/Bazz/Quux/...). For interview purposes the modulo version is more conventional; this version is the senior-level 'I see the pattern' answer.",
  }],
};

