// One Max Profit frame: the price array with the current day and the
// cheapest day seen so far marked.
const maxProfitFrame = (prices: number[], day: number, minDay: number, best = -1): ArraySnapshot => ({
  cells: prices.map((v, idx) => ({
    value: v,
    highlight: idx === best ? 'found' as const
      : idx === day ? 'i' as const : idx === minDay ? 'compare' as const : undefined,
  })),
  pointers: [
    ...(day >= 0 ? [{ index: day, label: 'day', color: 'red' as const }] : []),
    ...(minDay >= 0 && minDay !== day ? [{ index: minDay, label: 'min', color: 'indigo' as const }] : []),
  ],
});
const MAX_PROFIT_PRICES = [7, 1, 5, 3, 6, 4];
const MAX_PROFIT_BRUTE = [7, 1, 5, 3];
const maxProfitPairFrame = (i: number, j: number): ArraySnapshot => ({
  cells: MAX_PROFIT_BRUTE.map((v, idx) => ({
    value: v,
    highlight: idx === i ? 'i' as const : idx === j ? 'j' as const : undefined,
  })),
  pointers: [{ index: i, label: 'buy i', color: 'red' as const }, { index: j, label: 'sell j', color: 'amber' as const }],
});

const maxProfit: Explanation = {
  problem: 'Max Profit (Best Time to Buy/Sell Stock)',
  problemStatement: 'Given an array `prices` where `prices[i]` is the stock price on day i, return the maximum profit from one buy and one sell. You must buy before you sell. If no profit is possible, return 0.',
  approaches: [{
    id: 'one-pass',
    name: 'Single Pass — Track Min So Far (Best)',
    badge: 'best',
    intuition:
      "**Pretend to sell on every day, having bought on the cheapest day so far.** Walk the prices once with two numbers: `minPrice`, the lowest price seen so far (starts at Infinity), and `maxProfit`, the best profit found so far (starts at 0). For each price:\n" +
      "• price < minPrice: a new cheapest day. Record it as the buy candidate.\n" +
      "• otherwise: selling today earns price − minPrice. Keep it if it beats maxProfit.\n\n" +
      "**Why only the minimum matters:** for a sell on day j, the best buy is the cheapest day before j. Any other earlier day is more expensive, so it can only earn less. Tracking one running minimum therefore covers every buy/sell pair in O(n).",
    complexity: { time: 'O(n)', space: 'O(1)', verdict: 'Canonical — single linear pass' },
    pseudocode: [
      'minPrice = Infinity, maxProfit = 0',
      'for price in prices:',
      '  if price < minPrice: minPrice = price',
      '  else: maxProfit = max(maxProfit, price - minPrice)',
      'return maxProfit',
    ],
    example: { input: '[7, 1, 5, 3, 6, 4]', output: '5' },
    steps: [
      { title: 'Start: minPrice = Infinity, maxProfit = 0.', pseudoLine: 0,
        detail: 'Infinity guarantees the first price becomes the minimum.',
        array: maxProfitFrame(MAX_PROFIT_PRICES, -1, -1),
        computation: { label: 'minPrice, maxProfit', lhs: '∞, 0' } },
      { title: 'Day 0, price 7: 7 < ∞ → minPrice = 7.', pseudoLine: 2,
        array: maxProfitFrame(MAX_PROFIT_PRICES, 0, 0),
        computation: { label: 'minPrice, maxProfit', lhs: '7, 0' } },
      { title: 'Day 1, price 1: 1 < 7 → new low, minPrice = 1.', pseudoLine: 2,
        detail: 'Selling today cannot help: buying and selling on the same day earns 0.',
        array: maxProfitFrame(MAX_PROFIT_PRICES, 1, 1),
        computation: { label: 'minPrice, maxProfit', lhs: '1, 0' } },
      { title: 'Day 2, price 5: selling earns 5 − 1 = 4 > 0 → maxProfit = 4.', pseudoLine: 3,
        array: maxProfitFrame(MAX_PROFIT_PRICES, 2, 1),
        computation: { label: 'price − minPrice', lhs: '5 − 1', result: '4 (new best)' } },
      { title: 'Day 3, price 3: selling earns 3 − 1 = 2, not better than 4. maxProfit stays 4.', pseudoLine: 3,
        array: maxProfitFrame(MAX_PROFIT_PRICES, 3, 1),
        computation: { label: 'price − minPrice', lhs: '3 − 1', result: '2 (keep 4)' } },
      { title: 'Day 4, price 6: selling earns 6 − 1 = 5 > 4 → maxProfit = 5.', pseudoLine: 3,
        array: maxProfitFrame(MAX_PROFIT_PRICES, 4, 1),
        computation: { label: 'price − minPrice', lhs: '6 − 1', result: '5 (new best)' } },
      { title: 'Day 5, price 4: selling earns 4 − 1 = 3, not better than 5. maxProfit stays 5.', pseudoLine: 3,
        array: maxProfitFrame(MAX_PROFIT_PRICES, 5, 1),
        computation: { label: 'price − minPrice', lhs: '4 − 1', result: '3 (keep 5)' } },
      { title: 'All days read. Return 5: buy on day 1 at 1, sell on day 4 at 6.', pseudoLine: 4,
        array: maxProfitFrame(MAX_PROFIT_PRICES, -1, 1, 4),
        result: { found: true, value: '5' } },
    ],
    tradeoffs: 'Brute force checks every (i, j) pair → O(n²). The single-pass trick is the gold standard. Generalizes to "k transactions" via DP but that is a different problem.',
  },
  {
    id: 'brute-force',
    name: 'Brute Force — Try Every Pair (Baseline)',
    badge: 'baseline',
    intuition:
      "**Try every buy day with every later sell day.** Two nested loops: i is the buy day, j runs over every day after i, and the profit of that pair is prices[j] − prices[i]. Keep the largest one seen, starting from 0 so an all-losing input returns 0.\n\n" +
      "It is easy to verify, and it does n·(n−1)/2 checks, which times out on large inputs. Its value is as the starting point: noticing that for each j you only ever need the smallest prices[i] to its left is what collapses it into the one-pass O(n) version.",
    complexity: { time: 'O(n²)', space: 'O(1)', verdict: "Don't ship — for any n > 10⁴ this times out" },
    pseudocode: [
      'maxProfit = 0',
      'for i from 0 to n-1:',
      '  for j from i+1 to n-1:',
      '    profit = prices[j] - prices[i]',
      '    if profit > maxProfit: maxProfit = profit',
      'return maxProfit',
    ],
    example: { input: '[7, 1, 5, 3]', output: '4' },
    steps: [
      { title: 'Buy day 0 (7), sell day 1 (1): 1 − 7 = −6. A loss; maxProfit stays 0.', pseudoLine: 3,
        array: maxProfitPairFrame(0, 1),
        computation: { label: 'prices[j] − prices[i]', lhs: '1 − 7', result: '−6 (maxProfit 0)' } },
      { title: 'Buy day 0 (7), sell day 2 (5): 5 − 7 = −2. maxProfit stays 0.', pseudoLine: 3,
        array: maxProfitPairFrame(0, 2),
        computation: { label: 'prices[j] − prices[i]', lhs: '5 − 7', result: '−2 (maxProfit 0)' } },
      { title: 'Buy day 0 (7), sell day 3 (3): 3 − 7 = −4. maxProfit stays 0. j has run out, so i moves to 1.', pseudoLine: 3,
        array: maxProfitPairFrame(0, 3),
        computation: { label: 'prices[j] − prices[i]', lhs: '3 − 7', result: '−4 (maxProfit 0)' } },
      { title: 'Buy day 1 (1), sell day 2 (5): 5 − 1 = 4 > 0 → maxProfit = 4.', pseudoLine: 4,
        array: maxProfitPairFrame(1, 2),
        computation: { label: 'prices[j] − prices[i]', lhs: '5 − 1', result: '4 (new best)' } },
      { title: 'Buy day 1 (1), sell day 3 (3): 3 − 1 = 2, not above 4. i moves to 2.', pseudoLine: 3,
        array: maxProfitPairFrame(1, 3),
        computation: { label: 'prices[j] − prices[i]', lhs: '3 − 1', result: '2 (maxProfit 4)' } },
      { title: 'Buy day 2 (5), sell day 3 (3): 3 − 5 = −2. maxProfit stays 4. That was the last pair.', pseudoLine: 3,
        detail: 'i = 3 has no later day to sell on, so its inner loop runs zero times.',
        array: maxProfitPairFrame(2, 3),
        computation: { label: 'prices[j] − prices[i]', lhs: '3 − 5', result: '−2 (maxProfit 4)' } },
      { title: 'All 6 pairs checked. Return 4 (buy at 1, sell at 5).', pseudoLine: 5,
        array: { cells: MAX_PROFIT_BRUTE.map((v, idx) => ({ value: v, highlight: idx === 1 || idx === 2 ? 'found' as const : undefined })) },
        result: { found: true, value: '4' } },
    ],
    tradeoffs: 'Useful as a sanity check against the optimized version on small inputs (their outputs must match). Never the answer to ship.',
  }],
};

