// One Valid Parentheses frame: the input with the read position marked.
const VALID_PARENS_INPUT = '({[]})';
const validParenthesesFrame = (i: number, done = false): ArraySnapshot => ({
  cells: VALID_PARENS_INPUT.split('').map((c, idx) => ({
    value: c,
    highlight: done ? 'found' as const : idx === i ? 'i' as const : undefined,
  })),
  pointers: i >= 0 ? [{ index: i, label: 'ch', color: 'red' as const }] : [],
});
const validParenthesesStack = (s: string, action: 'push' | 'pop' | 'idle'): StackSnapshot => ({
  items: s.split('').map((c, idx) => ({ value: c, highlight: action === 'push' && idx === s.length - 1 ? 'new' as const : undefined })),
  action,
});

const validParentheses: Explanation = {
  problem: 'Valid Parentheses',
  problemStatement: 'Given a string of brackets `()[]{}`, return true if every opener has a matching closer in the correct order. `"({[]})"` is valid; `"([)]"` is not (the brackets cross). Compare with the simpler "Balanced Brackets (Count)" challenge which only checks counts and ignores ordering.',
  approaches: [{
    id: 'stack',
    name: 'Stack — Match Most-Recent Opener (Best)',
    badge: 'best',
    intuition:
      "**A stack remembers the openers that are still waiting for a closer.** A stack is a pile where you only add to, and take from, the top (last in, first out). Brackets nest, so the most recently opened bracket is always the next one that must close, which is exactly the top of the stack.\n\n" +
      "Scan left to right:\n" +
      "• opener `(`, `[`, `{`: push it.\n" +
      "• closer: pop the top. It must be the matching opener, else return false. An empty stack pops undefined, which also fails.\n" +
      "• at the end: the stack must be empty, or some opener was never closed.\n\n" +
      "A small map `{ ')': '(', ']': '[', '}': '{' }` gives each closer's opener in O(1).",
    complexity: { time: 'O(n)', space: 'O(n) — worst case all openers on the stack', verdict: 'Canonical — what every interviewer expects' },
    pseudocode: [
      'stack = [], pairs = { ")": "(", "]": "[", "}": "{" }',
      'for ch in s:',
      '  if ch is opener: stack.push(ch)',
      '  else if stack.pop() !== pairs[ch]: return false',
      'return stack.length === 0',
    ],
    example: { input: '"({[]})"', output: 'true' },
    steps: [
      { title: 'ch = "(" is an opener → push. Stack: (', pseudoLine: 2,
        array: validParenthesesFrame(0), stack: validParenthesesStack('(', 'push') },
      { title: 'ch = "{" is an opener → push. Stack: ( {', pseudoLine: 2,
        array: validParenthesesFrame(1), stack: validParenthesesStack('({', 'push') },
      { title: 'ch = "[" is an opener → push. Stack: ( { [', pseudoLine: 2,
        array: validParenthesesFrame(2), stack: validParenthesesStack('({[', 'push') },
      { title: 'ch = "]" is a closer → pop "[". pairs["]"] is "[" → match.', pseudoLine: 3,
        detail: 'The top of the stack is the innermost bracket still open, and it is the only one allowed to close now.',
        array: validParenthesesFrame(3), stack: validParenthesesStack('({', 'pop'),
        computation: { label: 'stack.pop() === pairs[ch]', lhs: '"[" === "["', result: 'true → keep going' } },
      { title: 'ch = "}" is a closer → pop "{". pairs["}"] is "{" → match.', pseudoLine: 3,
        array: validParenthesesFrame(4), stack: validParenthesesStack('(', 'pop'),
        computation: { label: 'stack.pop() === pairs[ch]', lhs: '"{" === "{"', result: 'true → keep going' } },
      { title: 'ch = ")" is a closer → pop "(". pairs[")"] is "(" → match.', pseudoLine: 3,
        array: validParenthesesFrame(5), stack: validParenthesesStack('', 'pop'),
        computation: { label: 'stack.pop() === pairs[ch]', lhs: '"(" === "("', result: 'true → keep going' } },
      { title: 'End of string. The stack is empty, so every opener was closed → return true.', pseudoLine: 4,
        detail: 'For "([)]" the fourth character ")" would pop "[" instead of "(", and the function would return false right there.',
        array: validParenthesesFrame(-1, true), stack: validParenthesesStack('', 'idle'),
        result: { found: true, value: 'true' } },
    ],
    tradeoffs: "A counter-only approach (track depth of each kind) is wrong — `([)]` would pass. The stack is what enforces correct nesting order. Don't confuse this with the simpler 'Balanced Brackets (Count)' challenge.",
  },
  {
    id: 'replace-pairs',
    name: 'Replace Inner Pairs (Cute but Slow)',
    badge: 'alternative',
    intuition:
      "**Delete innermost pairs until nothing is left.** Any valid bracket string contains an innermost pair: `()`, `[]` or `{}` with nothing between them. Deleting it leaves a string that is valid again, so you can keep going.\n\n" +
      "• Each pass deletes one `()`, one `[]` and one `{}` (a string replace with a plain string changes only the first match).\n" +
      "• If a pass changed nothing, you are stuck: the leftovers can never pair up, so stop.\n" +
      "• Valid exactly when the string ends up empty.\n\n" +
      "**Why this is O(n²):** each replace is O(n), and deeply nested input like `((((…))))` needs about n/2 passes. The stack approach is O(n). The value here is the argument: a valid string always reduces to nothing by removing innermost pairs.",
    complexity: { time: 'O(n²)', space: 'O(n)', verdict: "Don't ship at scale — but a fun alternative to think with" },
    pseudocode: [
      'while s.length > 0:',
      '  prev = s',
      '  s = s.replace("()", "").replace("[]", "").replace("{}", "")',
      '  if s === prev: break  // no progress → invalid',
      'return s.length === 0',
    ],
    example: { input: '"({[]})"', output: 'true' },
    steps: [
      { title: 'Pass 1, replace("()"): "({[]})" contains no "()", so nothing changes.', pseudoLine: 2,
        array: { cells: '({[]})'.split('').map(c => ({ value: c })) },
        computation: { label: 'replace("()", "")', lhs: '"({[]})"', op: '→', rhs: '"({[]})"' } },
      { title: 'Pass 1, replace("[]"): delete the innermost "[]" → "({})".', pseudoLine: 2,
        array: { cells: '({})'.split('').map((c, idx) => ({ value: c, highlight: idx === 1 || idx === 2 ? 'new' as const : undefined })) },
        computation: { label: 'replace("[]", "")', lhs: '"({[]})"', op: '→', rhs: '"({})"' } },
      { title: 'Pass 1, replace("{}"): the deletion just made "{}" adjacent, so delete it too → "()".', pseudoLine: 2,
        detail: 'The three replaces run in sequence on the same line, so a pair exposed by one replace can be removed by the next one in the same pass.',
        array: { cells: '()'.split('').map(c => ({ value: c, highlight: 'new' as const })) },
        computation: { label: 'replace("{}", "")', lhs: '"({})"', op: '→', rhs: '"()"' } },
      { title: 'Pass 1 made progress ("()" is not "({[]})"), so loop again.', pseudoLine: 3,
        array: { cells: '()'.split('').map(c => ({ value: c })) },
        computation: { label: 's === prev', lhs: '"()" === "({[]})"', result: 'false → keep looping' } },
      { title: 'Pass 2, replace("()") → "". The "[]" and "{}" replaces find nothing in an empty string.', pseudoLine: 2,
        computation: { label: 'replace("()", "")', lhs: '"()"', op: '→', rhs: '""' } },
      { title: 's.length is 0, so the while loop ends. Return true.', pseudoLine: 4,
        computation: { label: 's.length === 0', lhs: '0 === 0', result: 'true' },
        result: { found: true, value: 'true' } },
    ],
    tradeoffs: 'A nice teaching tool to convince yourself that the rule "every valid bracket string reduces to nothing by removing inner pairs" is true. But quadratic time makes it a non-starter for large inputs — always reach for the stack in production.',
  }],
};

