// One Merge Sorted Arrays frame. `taken` = how many values are in `merged`;
// the newest one is highlighted. i / j = undefined once that side is used up.
const MERGE_A = [1, 3, 5];
const MERGE_B = [2, 4, 6];
const MERGE_OUT = [1, 2, 3, 4, 5, 6];
const mergeSortedArraysFrame = (i: number, j: number, taken: number, done = false): DualArraySnapshot => ({
  left: { label: 'a (i)', cells: MERGE_A.map((v, idx) => ({ value: v, highlight: idx === i ? 'i' as const : undefined })), ...(i < MERGE_A.length ? { pointer: i } : {}) },
  right: { label: 'b (j)', cells: MERGE_B.map((v, idx) => ({ value: v, highlight: idx === j ? 'j' as const : undefined })), ...(j < MERGE_B.length ? { pointer: j } : {}) },
  result: { label: 'merged', cells: MERGE_OUT.slice(0, taken).map((v, idx) => ({ value: v, highlight: done ? 'found' as const : idx === taken - 1 ? 'new' as const : undefined })) },
});

const mergeSortedArrays: Explanation = {
  problem: 'Merge Sorted Arrays',
  problemStatement: 'Given two arrays already sorted in ascending order, merge them into one sorted array.',
  approaches: [{
    id: 'two-pointer',
    name: 'Two-Pointer Merge',
    badge: 'best',
    intuition:
      "**The smallest value left is always at the front of one of the two arrays.** Both inputs are sorted, so keep one pointer on each front: i into a, j into b.\n\n" +
      "• a[i] <= b[j]: take a[i] and move i right.\n" +
      "• otherwise: take b[j] and move j right.\n" +
      "• when one array is used up, everything left in the other is already sorted and larger, so append it as is.\n\n" +
      "Each value is copied exactly once, so it is O(m + n). Using <= (not <) takes from a on ties, which keeps equal values in their original order (a stable merge). This is the merge step of merge sort.",
    complexity: { time: 'O(m + n)', space: 'O(m + n)', verdict: 'Canonical' },
    pseudocode: [
      'i = 0, j = 0, out = []',
      'while i < m and j < n:',
      '  if a[i] <= b[j]: out.push(a[i++])',
      '  else: out.push(b[j++])',
      'append leftover from a or b',
      'return out',
    ],
    example: { input: 'a=[1,3,5], b=[2,4,6]', output: '[1,2,3,4,5,6]' },
    steps: [
      { title: 'i=0, j=0: 1 <= 2 → take 1 from a, i = 1.', pseudoLine: 2,
        dualArray: mergeSortedArraysFrame(0, 0, 1),
        computation: { label: 'a[i] <= b[j]', lhs: '1 <= 2', result: 'true → take a[i]' } },
      { title: 'i=1, j=0: 3 <= 2 is false → take 2 from b, j = 1.', pseudoLine: 3,
        dualArray: mergeSortedArraysFrame(1, 0, 2),
        computation: { label: 'a[i] <= b[j]', lhs: '3 <= 2', result: 'false → take b[j]' } },
      { title: 'i=1, j=1: 3 <= 4 → take 3 from a, i = 2.', pseudoLine: 2,
        dualArray: mergeSortedArraysFrame(1, 1, 3),
        computation: { label: 'a[i] <= b[j]', lhs: '3 <= 4', result: 'true → take a[i]' } },
      { title: 'i=2, j=1: 5 <= 4 is false → take 4 from b, j = 2.', pseudoLine: 3,
        dualArray: mergeSortedArraysFrame(2, 1, 4),
        computation: { label: 'a[i] <= b[j]', lhs: '5 <= 4', result: 'false → take b[j]' } },
      { title: 'i=2, j=2: 5 <= 6 → take 5 from a, i = 3.', pseudoLine: 2,
        dualArray: mergeSortedArraysFrame(2, 2, 5),
        computation: { label: 'a[i] <= b[j]', lhs: '5 <= 6', result: 'true → take a[i]' } },
      { title: 'i = 3 = m, so a is used up and the while loop stops. Append the leftover b[2] = 6.', pseudoLine: 4,
        detail: 'Everything left in b is sorted and at least as large as everything already merged, so it can be copied without comparing.',
        dualArray: mergeSortedArraysFrame(3, 2, 6),
        computation: { label: 'i < m and j < n', lhs: '3 < 3 and 2 < 3', result: 'false → append rest of b' } },
      { title: 'Return [1, 2, 3, 4, 5, 6]: 5 comparisons for 6 values.', pseudoLine: 5,
        dualArray: mergeSortedArraysFrame(3, 3, 6, true),
        result: { found: true, value: '[1,2,3,4,5,6]' } },
    ],
    tradeoffs: 'Concat-and-sort works but is O((m+n) log(m+n)) — wasteful when both inputs are already sorted. The merge step of mergesort is exactly this routine.',
  },
  {
    id: 'concat-sort',
    name: 'Concat + Sort (Lazy Alternative)',
    badge: 'baseline',
    intuition:
      "If you don't care about preserving the sorted-ness of the inputs, the laziest answer is `[...a, ...b].sort((x,y) => x − y)`. One spread to merge into a new array, one sort.\n\n" +
      "**Why this is wasteful:** the engine's sort is general-purpose — it doesn't know the inputs are already sorted, so it does O((m+n) log(m+n)) comparisons. The two-pointer merge does at most m+n comparisons. On two 100k-element arrays, that is roughly an 18× difference.\n\n" +
      "**Why people still write it:** it's one short line. In real code, when n is small or the arrays aren't actually sorted, this is the right call. In an interview, mention this as the 'if I didn't know they were sorted' baseline, then switch to two-pointer.",
    complexity: { time: 'O((m+n) log(m+n))', space: 'O(m+n)', verdict: 'Acceptable for tiny inputs; wasteful otherwise' },
    pseudocode: [
      'return [...a, ...b].sort((x, y) => x - y)',
    ],
    example: { input: 'a=[1,3,5], b=[2,4,6]', output: '[1,2,3,4,5,6]' },
    steps: [
      { title: 'Spread both arrays into a new one: [1,3,5,2,4,6].', pseudoLine: 0,
        array: { cells: [1,3,5,2,4,6].map(v => ({ value: v })) } },
      { title: 'Sort with numeric comparator (default sort is lexicographic — easy to forget!). Result: [1,2,3,4,5,6].',
        detail: '`.sort()` without a comparator sorts as strings, so [10, 2] sorts to [10, 2] — looks right, but [10, 2, 1] sorts to [1, 10, 2]. Always pass `(a,b) => a-b` for numbers.',
        pseudoLine: 0,
        array: { cells: [1,2,3,4,5,6].map(v => ({ value: v, highlight: 'found' as const })) },
        result: { found: true, value: '[1,2,3,4,5,6]' } },
    ],
    tradeoffs: 'Use when the inputs might not actually be sorted, or when n is small enough that the constant factor difference does not matter. For 99% of "merge two sorted lists" problems, the two-pointer is strictly better.',
    usesPolyfills: [
      { builtin: 'Array.prototype.sort', templateName: 'Array.sort',
        why: "the engine's general-purpose sort runs over the concatenated array" },
    ],
  }],
};

