// Find Duplicates (two sets): input with the read pointer, `seen` in
// insertion order on the right, `dups` as the result row.
const FIND_DUPLICATES_INPUT = [1, 2, 3, 2, 4, 1];
const findDuplicatesFrame = (i: number, seen: number[], dups: number[], mark: 'seen' | 'dup' | 'none'): DualArraySnapshot => ({
  left: { label: 'arr', cells: FIND_DUPLICATES_INPUT.map((v, idx) => ({ value: v, highlight: idx === i ? 'i' as const : undefined })), ...(i >= 0 ? { pointer: i } : {}) },
  right: { label: 'seen', cells: seen.map((v, idx) => ({ value: v, highlight: mark === 'seen' && idx === seen.length - 1 ? 'new' as const : mark === 'dup' && v === FIND_DUPLICATES_INPUT[i] ? 'hit' as const : undefined })) },
  result: { label: 'dups', cells: dups.map((v, idx) => ({ value: v, highlight: mark === 'dup' && idx === dups.length - 1 ? 'new' as const : undefined })) },
});
const FIND_DUPLICATES_SORTED = [1, 1, 2, 2, 3, 4];
const findDuplicatesSortedFrame = (i: number, found: number[] = []): ArraySnapshot => ({
  cells: FIND_DUPLICATES_SORTED.map((v, idx) => ({
    value: v,
    highlight: found.includes(idx) ? 'found' as const : idx === i ? 'i' as const : idx === i - 1 ? 'compare' as const : undefined,
  })),
  ...(i >= 0 ? { pointers: [{ index: i, label: 'i', color: 'red' as const }, { index: i - 1, label: 'i-1', color: 'indigo' as const }] } : {}),
});

const findDuplicates: Explanation = {
  problem: 'Find Duplicates',
  problemStatement: 'Return all values that appear more than once in an array.',
  approaches: [{
    id: 'two-sets',
    name: 'Two Sets — Seen + Duplicates',
    badge: 'best',
    intuition:
      "**One pass with two sets.** A Set stores each value once and answers has() in O(1). `seen` holds every value met so far; `dups` holds values met a second time. For each x:\n" +
      "• x is in seen: it has appeared before, so add it to dups.\n" +
      "• otherwise: add it to seen.\n\n" +
      "**Why dups is a Set too:** a value that appears three times hits the \"already seen\" branch twice. A Set ignores the second add, so it is still reported once.",
    complexity: { time: 'O(n)', space: 'O(n)', verdict: 'Canonical' },
    pseudocode: [
      'seen = new Set(), dups = new Set()',
      'for x in arr:',
      '  if seen.has(x): dups.add(x)',
      '  else: seen.add(x)',
      'return [...dups]',
    ],
    example: { input: '[1, 2, 3, 2, 4, 1]', output: '[2, 1]' },
    steps: [
      { title: 'x = 1: not in seen → add to seen.', pseudoLine: 3,
        dualArray: findDuplicatesFrame(0, [1], [], 'seen') },
      { title: 'x = 2: not in seen → add to seen.', pseudoLine: 3,
        dualArray: findDuplicatesFrame(1, [1, 2], [], 'seen') },
      { title: 'x = 3: not in seen → add to seen.', pseudoLine: 3,
        dualArray: findDuplicatesFrame(2, [1, 2, 3], [], 'seen') },
      { title: 'x = 2: already in seen → add 2 to dups.', pseudoLine: 2,
        detail: 'This is the second 2, so 2 is a duplicate.',
        dualArray: findDuplicatesFrame(3, [1, 2, 3], [2], 'dup') },
      { title: 'x = 4: not in seen → add to seen.', pseudoLine: 3,
        dualArray: findDuplicatesFrame(4, [1, 2, 3, 4], [2], 'seen') },
      { title: 'x = 1: already in seen → add 1 to dups.', pseudoLine: 2,
        dualArray: findDuplicatesFrame(5, [1, 2, 3, 4], [2, 1], 'dup') },
      { title: 'Convert dups to an array and return [2, 1], in the order each duplicate was found.', pseudoLine: 4,
        dualArray: findDuplicatesFrame(-1, [1, 2, 3, 4], [2, 1], 'none'),
        result: { found: true, value: '[2, 1]' } },
    ],
    tradeoffs: 'Frequency map (`Map<x, count>`) is identical work but lets you also report counts. Sort-then-scan is O(n log n) but O(1) space — pick when memory is tight.',
  },
  {
    id: 'sort-scan',
    name: 'Sort-Then-Scan (O(1) Extra Space)',
    badge: 'alternative',
    intuition:
      "**Sort first, so equal values become neighbours.** Then one scan finds every duplicate: arr[i] is a repeat when it equals arr[i-1].\n\n" +
      "• arr[i] === arr[i-1] and arr[i] !== arr[i-2]: the first repeat of this value → record it.\n" +
      "• arr[i] === arr[i-2] as well: a third copy, already recorded → skip.\n\n" +
      "It trades O(n log n) time for O(1) extra space. The sort mutates the input, so the caller's order is lost; copying first costs O(n) space again, which defeats the point.",
    complexity: { time: 'O(n log n)', space: 'O(1) if mutating allowed; O(n) for a copy', verdict: 'When memory matters more than time' },
    pseudocode: [
      'arr.sort((a,b) => a - b)',
      'dups = []',
      'for i from 1 to n-1:',
      '  if arr[i] === arr[i-1] and arr[i] !== arr[i-2]:',
      '    dups.push(arr[i])',
      'return dups',
    ],
    example: { input: '[1, 2, 3, 2, 4, 1]', output: '[1, 2]' },
    steps: [
      { title: 'Sort: [1, 2, 3, 2, 4, 1] → [1, 1, 2, 2, 3, 4].', pseudoLine: 0,
        array: findDuplicatesSortedFrame(-1) },
      { title: 'i=1: arr[1] = 1 equals arr[0] = 1, and arr[-1] is undefined → push 1.', pseudoLine: 4,
        detail: 'Reading arr[-1] on an array gives undefined, never equal to a number, so the guard is safe at i = 1.',
        array: findDuplicatesSortedFrame(1, [0, 1]),
        computation: { label: 'arr[i] === arr[i-1] and arr[i] !== arr[i-2]', lhs: '1 === 1 and 1 !== undefined', result: 'true → push 1' } },
      { title: 'i=2: arr[2] = 2 differs from arr[1] = 1 → not a repeat.', pseudoLine: 3,
        array: findDuplicatesSortedFrame(2, [0, 1]),
        computation: { label: 'arr[i] === arr[i-1]', lhs: '2 === 1', result: 'false' } },
      { title: 'i=3: arr[3] = 2 equals arr[2] = 2, and arr[1] = 1 is not 2 → push 2.', pseudoLine: 4,
        array: findDuplicatesSortedFrame(3, [0, 1, 2, 3]),
        computation: { label: 'arr[i] === arr[i-1] and arr[i] !== arr[i-2]', lhs: '2 === 2 and 2 !== 1', result: 'true → push 2' } },
      { title: 'i=4: arr[4] = 3 differs from arr[3] = 2 → not a repeat.', pseudoLine: 3,
        array: findDuplicatesSortedFrame(4, [0, 1, 2, 3]),
        computation: { label: 'arr[i] === arr[i-1]', lhs: '3 === 2', result: 'false' } },
      { title: 'i=5: arr[5] = 4 differs from arr[4] = 3 → not a repeat.', pseudoLine: 3,
        detail: 'With [2, 2, 2], the third 2 would pass the first test but fail arr[i] !== arr[i-2], so 2 is still pushed only once.',
        array: findDuplicatesSortedFrame(5, [0, 1, 2, 3]),
        computation: { label: 'arr[i] === arr[i-1]', lhs: '4 === 3', result: 'false' } },
      { title: 'Scan finished. Return [1, 2].', pseudoLine: 5,
        array: findDuplicatesSortedFrame(-1, [0, 1, 2, 3]),
        result: { found: true, value: '[1, 2]' } },
    ],
    tradeoffs: 'Cleanest if you can mutate the input. The triple-equal-guard is the part candidates often miss — without it, [1,1,1] would emit 1 twice.',
    usesPolyfills: [
      { builtin: 'Array.prototype.sort', templateName: 'Array.sort',
        why: 'sorting groups equal elements together for the linear scan' },
    ],
  }],
};

