// Remove Duplicates frames: the input with the read pointer, plus the
// `seen` Map (or Set) contents as of this step.
const REMOVE_DUPLICATES_INPUT = [1, 2, 2, 3, 1, 4];
const removeDuplicatesFrame = (i: number): ArraySnapshot => ({
  cells: REMOVE_DUPLICATES_INPUT.map((v, idx) => ({ value: v, highlight: idx === i ? 'i' as const : undefined })),
  ...(i >= 0 ? { pointers: [{ index: i, label: 'x', color: 'red' as const }] } : {}),
});
const removeDuplicatesMap = (keys: number[], mark?: number, kind: 'new' | 'hit' = 'new'): MapSnapshot => ({
  entries: keys.map(k => ({ key: k, value: 'true', highlight: k === mark ? kind : undefined })),
});
const removeDuplicatesSet = (keys: number[], mark?: number, kind: 'new' | 'hit' = 'new'): SetSnapshot => ({
  items: keys.map(k => ({ value: k, highlight: k === mark ? kind : undefined })),
});

const removeDuplicates: Explanation = {
  problem: 'Remove Duplicates',
  problemStatement: 'Return the array with duplicates removed, keeping the first occurrence, without using Set.',
  approaches: [{
    id: 'map',
    name: 'Map as a "Seen" Table',
    badge: 'best',
    intuition:
      "**The challenge bans Set, so you build the lookup yourself.** Walk the array once. For each value, ask a hash map \"have I seen this?\" If not, record it and push it to the result. Pushing on first sight is what keeps the original order.\n\n" +
      "**Why a Map and not a plain object.** Object keys are always strings, so 1 and \"1\" would land on the same key and one of them would be dropped. A Map keeps each key's type, and it treats NaN as equal to NaN, so it dedupes exactly the way Set would. has() and set() are O(1) on average, which makes the whole pass O(n).",
    complexity: { time: 'O(n)', space: 'O(n)', verdict: 'Meets the constraints' },
    pseudocode: [
      'seen = new Map(), out = []',
      'for x in arr:',
      '  if !seen.has(x):',
      '    seen.set(x, true); out.push(x)',
      'return out',
    ],
    example: { input: '[1, 2, 2, 3, 1, 4]', output: '[1, 2, 3, 4]' },
    steps: [
      { title: 'x = 1: seen.has(1) is false → record it and push. out = [1].', pseudoLine: 3,
        array: removeDuplicatesFrame(0), map: removeDuplicatesMap([1], 1),
        computation: { label: 'out', lhs: '[1]' } },
      { title: 'x = 2: seen.has(2) is false → record it and push. out = [1, 2].', pseudoLine: 3,
        array: removeDuplicatesFrame(1), map: removeDuplicatesMap([1, 2], 2),
        computation: { label: 'out', lhs: '[1, 2]' } },
      { title: 'x = 2: seen.has(2) is true → skip it. out stays [1, 2].', pseudoLine: 2,
        detail: 'The first 2 is already in out, in its original position. Skipping later copies is what "keep the first occurrence" means.',
        array: removeDuplicatesFrame(2), map: removeDuplicatesMap([1, 2], 2, 'hit'),
        computation: { label: 'out', lhs: '[1, 2]' } },
      { title: 'x = 3: seen.has(3) is false → record it and push. out = [1, 2, 3].', pseudoLine: 3,
        array: removeDuplicatesFrame(3), map: removeDuplicatesMap([1, 2, 3], 3),
        computation: { label: 'out', lhs: '[1, 2, 3]' } },
      { title: 'x = 1: seen.has(1) is true → skip it. out stays [1, 2, 3].', pseudoLine: 2,
        array: removeDuplicatesFrame(4), map: removeDuplicatesMap([1, 2, 3], 1, 'hit'),
        computation: { label: 'out', lhs: '[1, 2, 3]' } },
      { title: 'x = 4: seen.has(4) is false → record it and push. out = [1, 2, 3, 4].', pseudoLine: 3,
        array: removeDuplicatesFrame(5), map: removeDuplicatesMap([1, 2, 3, 4], 4),
        computation: { label: 'out', lhs: '[1, 2, 3, 4]' } },
      { title: 'Every value read. Return [1, 2, 3, 4].', pseudoLine: 4,
        array: removeDuplicatesFrame(-1), map: removeDuplicatesMap([1, 2, 3, 4]),
        result: { found: true, value: '[1, 2, 3, 4]' } },
    ],
    tradeoffs: 'A plain object (ideally Object.create(null), so "toString" is not already a key) works when every value has the same type, but it merges 1 and "1". filter + indexOf is banned here, and it is O(n²) and never finds NaN. Say in the interview that in real code [...new Set(arr)] is the right answer; the ban exists to test that you know what a Set does underneath.',
  },
  {
    id: 'spread-set',
    name: 'Set Spread (Real-Code One-Liner)',
    badge: 'alternative',
    intuition:
      "**Not allowed in this challenge, but worth knowing and worth saying.** [...new Set(arr)] builds a Set from the array (a Set keeps each value once) and spreads it back into an array. Set iteration follows insertion order, so the first occurrence of each value stays in place.\n\n" +
      "It is the same idea as the Map approach, with the lookup table built into the language: `new Set(arr)` runs the same loop internally, calling add() for each value, and add() of a value already present does nothing. The downside is that you cannot do anything else during the pass, such as counting how often each value appeared; that needs the explicit loop.",
    complexity: { time: 'O(n)', space: 'O(n)', verdict: 'Use in production, not here' },
    pseudocode: [
      'return [...new Set(arr)]',
    ],
    example: { input: '[1, 2, 2, 3, 1, 4]', output: '[1, 2, 3, 4]' },
    steps: [
      { title: 'new Set reads 1 → add(1). Set: {1}.', pseudoLine: 0,
        array: removeDuplicatesFrame(0), set: removeDuplicatesSet([1], 1) },
      { title: 'Reads 2 → add(2). Set: {1, 2}.', pseudoLine: 0,
        array: removeDuplicatesFrame(1), set: removeDuplicatesSet([1, 2], 2) },
      { title: 'Reads 2 → add(2) finds 2 already there and does nothing.', pseudoLine: 0,
        array: removeDuplicatesFrame(2), set: removeDuplicatesSet([1, 2], 2, 'hit') },
      { title: 'Reads 3 → add(3). Set: {1, 2, 3}.', pseudoLine: 0,
        array: removeDuplicatesFrame(3), set: removeDuplicatesSet([1, 2, 3], 3) },
      { title: 'Reads 1 → already there, nothing changes.', pseudoLine: 0,
        array: removeDuplicatesFrame(4), set: removeDuplicatesSet([1, 2, 3], 1, 'hit') },
      { title: 'Reads 4 → add(4). Set: {1, 2, 3, 4}.', pseudoLine: 0,
        array: removeDuplicatesFrame(5), set: removeDuplicatesSet([1, 2, 3, 4], 4) },
      { title: 'Spread back into an array: [1, 2, 3, 4], in first-seen order.', pseudoLine: 0,
        array: { cells: [1,2,3,4].map(v => ({ value: v, highlight: 'found' as const })) },
        result: { found: true, value: '[1, 2, 3, 4]' } },
    ],
    tradeoffs: "Shortest and fastest to write. Set and Map both use SameValueZero equality, so NaN dedupes correctly here too, while indexOf-based versions drop it.",
  }],
};

