// Clean Mixed Array: the example and small frame builders for its traces.
const CLEAN_MIXED_INPUT: (number | string)[] = [5, 'a', 3, 5, 1];
const cleanMixedArrayInput = (i: number, kept: number[] = []): ArraySnapshot => ({
  cells: CLEAN_MIXED_INPUT.map((v, idx) => ({
    value: typeof v === 'string' ? `"${v}"` : v,
    highlight: idx === i ? 'i' as const : kept.includes(idx) ? 'found' as const : undefined,
  })),
  ...(i >= 0 ? { pointers: [{ index: i, label: 'x', color: 'red' as const }] } : {}),
});
const cleanMixedArrayCells = (values: number[], mark: Record<number, Highlight> = {}, pointers: ArraySnapshot['pointers'] = []): ArraySnapshot => ({
  cells: values.map((v, idx) => ({ value: v, highlight: mark[idx] })),
  ...(pointers.length ? { pointers } : {}),
});

