// Find Missing Number frame: [3, 0, 1] with the element being read marked.
const FIND_MISSING_INPUT = [3, 0, 1];
const findMissingNumberFrame = (i: number, doneUpTo = -1): ArraySnapshot => ({
  cells: FIND_MISSING_INPUT.map((v, idx) => ({ value: v, highlight: idx === i ? 'i' as const : idx <= doneUpTo ? 'compare' as const : undefined })),
  ...(i >= 0 ? { pointers: [{ index: i, label: 'x', color: 'red' as const }] } : {}),
});

const findMissingNumber: Explanation = {
  problem: 'Find Missing Number',
  problemStatement: 'Given an array of n distinct numbers from 0..n with one missing, find the missing number.',
  approaches: [{
    id: 'sum',
    name: 'Sum Formula',
    badge: 'best',
    intuition:
      "**You know what the total should be, so the shortfall is the missing number.** The array has n slots, and the numbers 0..n are n + 1 values, so exactly one is absent.\n\n" +
      "• expected = 0 + 1 + … + n = n·(n+1)/2 (Gauss's formula: pair the smallest with the largest, and every pair sums to n)\n" +
      "• actual = the sum of the array, one pass\n" +
      "• missing = expected − actual\n\n" +
      "Every present number appears in both sums and cancels, so only the missing one is left. O(n) time, O(1) space.",
    complexity: { time: 'O(n)', space: 'O(1)', verdict: 'Canonical' },
    pseudocode: [
      'n = arr.length',
      'expected = n * (n + 1) / 2',
      'actual = 0',
      'for x in arr: actual += x',
      'return expected - actual',
    ],
    example: { input: '[3, 0, 1] (n=3)', output: '2' },
    steps: [
      { title: 'n = 3, so the full set is 0..3 and expected = 3·4/2 = 6.', pseudoLine: 1,
        array: findMissingNumberFrame(-1),
        computation: { label: 'expected', lhs: '3·4', op: '/', rhs: '2', result: '6' } },
      { title: 'x = 3: actual = 0 + 3 = 3.', pseudoLine: 3,
        array: findMissingNumberFrame(0),
        computation: { label: 'actual += x', lhs: '0 + 3', result: '3' } },
      { title: 'x = 0: actual = 3 + 0 = 3.', pseudoLine: 3,
        array: findMissingNumberFrame(1, 0),
        computation: { label: 'actual += x', lhs: '3 + 0', result: '3' } },
      { title: 'x = 1: actual = 3 + 1 = 4.', pseudoLine: 3,
        array: findMissingNumberFrame(2, 1),
        computation: { label: 'actual += x', lhs: '3 + 1', result: '4' } },
      { title: 'missing = 6 − 4 = 2.', pseudoLine: 4,
        detail: '0 + 1 + 2 + 3 = 6 and 3 + 0 + 1 = 4. Only the 2 is in the first sum and not the second.',
        array: findMissingNumberFrame(-1, 2),
        computation: { label: 'expected − actual', lhs: '6', op: '−', rhs: '4', result: '2' },
        result: { found: true, value: '2' } },
    ],
    tradeoffs: 'XOR variant (`xor of indices xor of values`) avoids potential overflow on huge n in fixed-width languages — irrelevant in JS bigint, but the canonical answer in C/C++ interviews. Set lookup is O(n) time + space, slower in practice.',
  },
  {
    id: 'xor',
    name: 'XOR Trick (Overflow-Safe)',
    badge: 'alternative',
    intuition:
      "**XOR every number 0..n and every array value together; the pairs cancel and the missing one is left.** XOR (`^`, bitwise exclusive-or) compares two numbers bit by bit and keeps a 1 where the bits differ. Two facts make it work:\n" +
      "• `a ^ a === 0`: a number XORed with itself vanishes.\n" +
      "• `a ^ 0 === a`, and the order of XORs does not matter.\n\n" +
      "Each present number is XORed in twice (once from 0..n, once from the array) and vanishes. The missing number is XORed in only once, so it is what remains.\n\n" +
      "**Why interviewers like it:** the sum approach can overflow a fixed-width int in C/C++/Java for large n. XOR never grows past the largest input. In JS numbers are exact up to 2⁵³, so the overflow argument is academic, but XOR is still the expected \"overflow-safe\" answer.",
    complexity: { time: 'O(n)', space: 'O(1)', verdict: 'Best for C/C++/Java; equivalent in JS' },
    pseudocode: [
      'result = 0',
      'for i from 0 to n:        // include n itself',
      '  result ^= i',
      'for x in arr:',
      '  result ^= x',
      'return result',
    ],
    example: { input: '[3, 0, 1] (n=3)', output: '2' },
    steps: [
      { title: 'i = 0: result = 0 ^ 0 = 0.', pseudoLine: 2,
        computation: { label: 'result ^= i', lhs: '0 ^ 0', result: '0' } },
      { title: 'i = 1: result = 0 ^ 1 = 1.', pseudoLine: 2,
        computation: { label: 'result ^= i', lhs: '0 ^ 1', result: '1' } },
      { title: 'i = 2: result = 1 ^ 2 = 3.', pseudoLine: 2,
        detail: 'In binary 01 ^ 10 = 11. The bits differ in both places, so both are 1.',
        computation: { label: 'result ^= i', lhs: '1 ^ 2', result: '3' } },
      { title: 'i = 3: result = 3 ^ 3 = 0. The first loop is done: 0 ^ 1 ^ 2 ^ 3 = 0.', pseudoLine: 2,
        computation: { label: 'result ^= i', lhs: '3 ^ 3', result: '0' } },
      { title: 'x = 3: result = 0 ^ 3 = 3.', pseudoLine: 4,
        array: findMissingNumberFrame(0),
        computation: { label: 'result ^= x', lhs: '0 ^ 3', result: '3' } },
      { title: 'x = 0: result = 3 ^ 0 = 3.', pseudoLine: 4,
        array: findMissingNumberFrame(1, 0),
        computation: { label: 'result ^= x', lhs: '3 ^ 0', result: '3' } },
      { title: 'x = 1: result = 3 ^ 1 = 2.', pseudoLine: 4,
        array: findMissingNumberFrame(2, 1),
        computation: { label: 'result ^= x', lhs: '3 ^ 1', result: '2' } },
      { title: 'Return 2. Reordered, the whole run is (0^0) ^ (1^1) ^ (3^3) ^ 2 = 2: every present number cancelled with its twin.', pseudoLine: 5,
        array: findMissingNumberFrame(-1, 2),
        computation: { label: 'all XORs, regrouped', lhs: '0 ^ 0 ^ 0 ^ 2', result: '2' },
        result: { found: true, value: '2' } },
    ],
    tradeoffs: 'Same complexity as the sum approach in JS. The key skill being tested is recognizing the XOR identity — interviewers often follow up with the related "find the duplicate" or "every-element-twice-except-one" problems where XOR shines.',
  }],
};


// ====================================================================

// Find All Missing Numbers frame: the (mutating) nums array, the index being
// read, and the home slot being marked.
const findAllMissingNumbersFrame = (nums: number[], read: number, home = -1, mark: 'new' | 'hit' = 'new'): ArraySnapshot => ({
  cells: nums.map((v, idx) => ({
    value: v,
    highlight: idx === home ? mark : idx === read ? 'i' as const : undefined,
  })),
  pointers: [
    ...(read >= 0 ? [{ index: read, label: 'i', color: 'red' as const }] : []),
    ...(home >= 0 && home !== read ? [{ index: home, label: 'home', color: 'emerald' as const }] : []),
  ],
});
const findAllMissingNumbersScan = (i: number, found: number[]): ArraySnapshot => ({
  cells: [2, -2, -3, 3].map((v, idx) => ({
    value: v,
    highlight: found.includes(idx) ? 'found' as const : idx === i ? 'i' as const : undefined,
  })),
  pointers: [{ index: i, label: 'i', color: 'red' as const }],
});
const findAllMissingNumbersSet = (items: number[], mark?: number, kind: 'new' | 'hit' = 'new'): SetSnapshot => ({
  items: items.map(v => ({ value: v, highlight: v === mark ? kind : undefined })),
});

const findAllMissingNumbers: Explanation = {
  problem: 'Find All Missing Numbers',
  problemStatement: 'Given an array of n values each in [1, n], with duplicates allowed, return every value in [1, n] that never appears.',
  approaches: [{
    id: 'sign-marking',
    name: 'Sign Marking (In Place)',
    badge: 'best',
    intuition:
      "**The given that unlocks everything:** every value sits in [1, n], so value v has a natural home at index v - 1. The array is therefore already the right size to be its own lookup table — you do not need a second one.\n\n" +
      "**The trick:** you need one bit per slot to record \"I saw this value\", and every slot already has a spare bit — its sign. Pass one flips the sign at the home index of each value seen. Pass two reports every index still positive, because nothing ever marked it.\n\n" +
      "**Why Math.abs is not optional:** by the time you read nums[i], an earlier value may already have flipped it negative. You want the original magnitude, not the marker.",
    complexity: { time: 'O(n)', space: 'O(1)', verdict: 'The graded answer' },
    pseudocode: [
      'for each value v in nums:',
      '  home = abs(v) - 1',
      '  if nums[home] > 0: nums[home] = -nums[home]',
      'for i from 0 to n-1:',
      '  if nums[i] > 0: add i + 1 to missing',
      'return missing',
    ],
    example: { input: '[2, 2, 3, 3]', output: '[1, 4]' },
    steps: [
      { title: 'i=0: v = 2 → home = 1. nums[1] = 2 is positive → flip it to −2.', pseudoLine: 2,
        detail: 'A negative sign at index 1 now means "the value 2 was seen".',
        array: findAllMissingNumbersFrame([2, -2, 3, 3], 0, 1) },
      { title: 'i=1: nums[1] is −2, so v = abs(−2) = 2 → home = 1. Already negative → leave it.', pseudoLine: 2,
        detail: 'Without abs, home would be −3, an index that does not exist. Leaving a mark alone is why duplicates are harmless: marking twice is the same as marking once.',
        array: findAllMissingNumbersFrame([2, -2, 3, 3], 1, 1, 'hit'),
        computation: { label: 'home = abs(v) − 1', lhs: 'abs(−2) − 1', result: '1' } },
      { title: 'i=2: v = 3 → home = 2. nums[2] = 3 is positive → flip it to −3.', pseudoLine: 2,
        detail: 'Here the value happens to sit in its own home, so the cell being read is the one that gets marked.',
        array: findAllMissingNumbersFrame([2, -2, -3, 3], 2, 2) },
      { title: 'i=3: v = 3 → home = 2. Already negative → leave it. Pass one is done.', pseudoLine: 2,
        array: findAllMissingNumbersFrame([2, -2, -3, 3], 3, 2, 'hit') },
      { title: 'Scan i=0: nums[0] = 2 is positive → nobody marked it, so 1 is missing.', pseudoLine: 4,
        array: findAllMissingNumbersScan(0, [0]),
        computation: { label: 'missing', lhs: '[1]' } },
      { title: 'Scan i=1: nums[1] = −2 is negative → 2 was seen.', pseudoLine: 4,
        array: findAllMissingNumbersScan(1, [0]),
        computation: { label: 'missing', lhs: '[1]' } },
      { title: 'Scan i=2: nums[2] = −3 is negative → 3 was seen.', pseudoLine: 4,
        array: findAllMissingNumbersScan(2, [0]),
        computation: { label: 'missing', lhs: '[1]' } },
      { title: 'Scan i=3: nums[3] = 3 is positive → 4 is missing.', pseudoLine: 4,
        detail: 'Only the sign matters in pass two. The 3 stored here is just the original value that nobody overwrote.',
        array: findAllMissingNumbersScan(3, [0, 3]),
        computation: { label: 'missing', lhs: '[1, 4]' } },
      { title: 'Return [1, 4].', pseudoLine: 5,
        array: { cells: [2, -2, -3, 3].map((v, idx) => ({ value: v, highlight: idx === 0 || idx === 3 ? 'found' as const : undefined })) },
        result: { found: true, value: '[1, 4]' } },
    ],
    tradeoffs:
      "It MUTATES the caller's array — every present value comes back negative. Volunteer that; it is the price of O(1) space and an interviewer will ask. Restoring the signs in a third pass is easy if the caller needs the data intact. The sibling problem \"find all duplicates\" is the identical trick with the test inverted: report v at the moment you find its home already marked.",
  },
  {
    id: 'set',
    name: 'Set of Present Values',
    badge: 'alternative',
    intuition:
      'Build a Set of everything present, then walk 1..n and collect whatever the Set does not contain. It answers the question directly rather than cleverly, and it leaves the input untouched.\n\n' +
      'This is the version to write in real application code. Destroying the caller’s array to avoid allocating one array nobody was short of is a bad trade outside an interview.',
    complexity: { time: 'O(n)', space: 'O(n)', verdict: 'What you would actually ship' },
    pseudocode: [
      'present = new Set(nums)',
      'for v from 1 to n:',
      '  if not present.has(v): add v to missing',
      'return missing',
    ],
    example: { input: '[2, 2, 3, 3]', output: '[1, 4]' },
    steps: [
      { title: 'new Set reads 2 → add. Set: {2}.', pseudoLine: 0,
        set: findAllMissingNumbersSet([2], 2) },
      { title: 'Reads 2 again → already there, nothing changes.', pseudoLine: 0,
        set: findAllMissingNumbersSet([2], 2, 'hit') },
      { title: 'Reads 3 → add. Set: {2, 3}.', pseudoLine: 0,
        set: findAllMissingNumbersSet([2, 3], 3) },
      { title: 'Reads 3 again → nothing changes. present = {2, 3}.', pseudoLine: 0,
        set: findAllMissingNumbersSet([2, 3], 3, 'hit') },
      { title: 'v = 1: present.has(1) is false → missing = [1].', pseudoLine: 2,
        set: findAllMissingNumbersSet([2, 3]),
        computation: { label: 'present.has(1)', lhs: 'false', op: '→', rhs: 'missing = [1]' } },
      { title: 'v = 2: present.has(2) is true → skip.', pseudoLine: 2,
        set: findAllMissingNumbersSet([2, 3], 2, 'hit'),
        computation: { label: 'present.has(2)', lhs: 'true', op: '→', rhs: 'missing = [1]' } },
      { title: 'v = 3: present.has(3) is true → skip.', pseudoLine: 2,
        set: findAllMissingNumbersSet([2, 3], 3, 'hit'),
        computation: { label: 'present.has(3)', lhs: 'true', op: '→', rhs: 'missing = [1]' } },
      { title: 'v = 4: present.has(4) is false → missing = [1, 4].', pseudoLine: 2,
        set: findAllMissingNumbersSet([2, 3]),
        computation: { label: 'present.has(4)', lhs: 'false', op: '→', rhs: 'missing = [1, 4]' } },
      { title: 'v has passed n = 4. Return [1, 4].', pseudoLine: 3,
        set: findAllMissingNumbersSet([2, 3]),
        result: { found: true, value: '[1, 4]' } },
    ],
    tradeoffs: 'O(n) space is the whole objection, and only when the question forbids it. A boolean seen[] array of length n + 1 costs the same asymptotically but indexes instead of hashing, which is measurably faster on tight loops and reads more plainly.',
  }],
};

// ====================================================================

// First Missing Positive frame: nums as of this moment, i, and (optionally)
// the home slot of the value at i.
const firstMissingPositiveFrame = (nums: number[], i: number, home = -1, placed: number[] = []): ArraySnapshot => ({
  cells: nums.map((v, idx) => ({
    value: v,
    highlight: idx === i ? 'i' as const : idx === home ? 'compare' as const : placed.includes(idx) ? 'found' as const : undefined,
  })),
  pointers: [
    ...(i >= 0 ? [{ index: i, label: 'i', color: 'indigo' as const }] : []),
    ...(home >= 0 && home !== i ? [{ index: home, label: 'home', color: 'emerald' as const }] : []),
  ],
});
const firstMissingPositiveSet = (items: number[], mark?: number, kind: 'new' | 'hit' = 'new'): SetSnapshot => ({
  items: items.map(v => ({ value: v, highlight: v === mark ? kind : undefined })),
});

const firstMissingPositive: Explanation = {
  problem: 'First Missing Positive',
  problemStatement: 'Given an unsorted array of arbitrary integers, find the smallest positive integer that does not appear, in O(n) time and O(1) space.',
  approaches: [{
    id: 'index-cycling',
    name: 'Index Cycling (Swap Into Home)',
    badge: 'best',
    intuition:
      '**Say this first, before any code:** with only n slots, the answer can never be larger than n + 1. The worst case is that the array holds exactly 1..n, and then the answer is n + 1. So you are not searching the integers — you are searching n + 1 candidates, and you already own n slots to record them in. That bound is the entire reason O(1) space is possible.\n\n' +
      '**The method:** send every in-range value v to its home, index v - 1, by swapping. Anything negative, zero, or larger than n is noise and stays wherever it lands. When the array is arranged, the first index i that does not hold i + 1 names the answer.\n\n' +
      '**Why a while, not an if:** the value swapped into slot i also needs a home, so keep swapping until slot i holds noise or a value already at home.',
    complexity: { time: 'O(n)', space: 'O(1)', verdict: 'The graded answer' },
    pseudocode: [
      'for i from 0 to n-1:',
      '  while 1 <= nums[i] <= n and nums[nums[i]-1] != nums[i]:',
      '    swap nums[i] with nums[nums[i]-1]',
      'for i from 0 to n-1:',
      '  if nums[i] != i + 1: return i + 1',
      'return n + 1',
    ],
    example: { input: '[3, 4, -1, 1]', output: '2' },
    steps: [
      { title: 'i=0 holds 3. Its home is index 2, which holds −1, not 3 → swap.', pseudoLine: 2,
        array: firstMissingPositiveFrame([3, 4, -1, 1], 0, 2),
        computation: { label: 'home of 3', lhs: '3 − 1', result: 'index 2' } },
      { title: 'After the swap i=0 holds −1. Out of range, so it is noise → stop the while, move to i=1.', pseudoLine: 1,
        detail: '3 has reached its final home and will never move again. That is why the nested while does not make this quadratic.',
        array: firstMissingPositiveFrame([-1, 4, 3, 1], 0, -1, [2]),
        computation: { label: '1 <= nums[0] <= 4', lhs: '1 <= −1', result: 'false → stop' } },
      { title: 'i=1 holds 4. Its home is index 3, which holds 1, not 4 → swap.', pseudoLine: 2,
        array: firstMissingPositiveFrame([-1, 4, 3, 1], 1, 3, [2]),
        computation: { label: 'home of 4', lhs: '4 − 1', result: 'index 3' } },
      { title: 'Now i=1 holds 1, whose home is index 0 (holding −1) → swap again.', pseudoLine: 2,
        detail: 'This is why it is a while, not an if: the value that arrived needs a home too.',
        array: firstMissingPositiveFrame([-1, 1, 3, 4], 1, 0, [2, 3]),
        computation: { label: 'home of 1', lhs: '1 − 1', result: 'index 0' } },
      { title: 'Now i=1 holds −1: noise → stop, move to i=2.', pseudoLine: 1,
        array: firstMissingPositiveFrame([1, -1, 3, 4], 1, -1, [0, 2, 3]),
        computation: { label: '1 <= nums[1] <= 4', lhs: '1 <= −1', result: 'false → stop' } },
      { title: 'i=2 holds 3, and nums[2] is 3: already home → nothing to do.', pseudoLine: 1,
        detail: 'This clause is also what prevents an infinite loop on duplicates: swapping two equal values would change nothing, forever.',
        array: firstMissingPositiveFrame([1, -1, 3, 4], 2, -1, [0, 3]),
        computation: { label: 'nums[nums[2]−1] != nums[2]', lhs: '3 != 3', result: 'false → stop' } },
      { title: 'i=3 holds 4, and nums[3] is 4: already home. The arranging loop is done.', pseudoLine: 1,
        array: firstMissingPositiveFrame([1, -1, 3, 4], 3, -1, [0, 2]),
        computation: { label: 'nums[nums[3]−1] != nums[3]', lhs: '4 != 4', result: 'false → stop' } },
      { title: 'Scan i=0: nums[0] is 1 = 0 + 1, as it should be.', pseudoLine: 4,
        array: firstMissingPositiveFrame([1, -1, 3, 4], 0, -1, [2, 3]),
        computation: { label: 'nums[i] != i + 1', lhs: '1 != 1', result: 'false → keep scanning' } },
      { title: 'Scan i=1: nums[1] is −1, not 2 → return 2.', pseudoLine: 4,
        array: firstMissingPositiveFrame([1, -1, 3, 4], 1, -1, [0, 2, 3]),
        computation: { label: 'nums[i] != i + 1', lhs: '−1 != 2', result: 'true → return 2' },
        result: { found: true, value: '2' } },
    ],
    tradeoffs:
      'The clause that stops an infinite loop is nums[nums[i]-1] !== nums[i]. With a duplicate, the home slot already holds that value, so swapping would exchange two equal numbers forever — drop it and [1, 1] hangs. That is the single most common way to fail this question. The nested while also looks quadratic and is not: each swap places one value in its final home permanently, so there are at most n swaps in the whole run.',
  },
  {
    id: 'set',
    name: 'Set Lookup (Baseline)',
    badge: 'baseline',
    intuition:
      'Put everything in a Set, then count upward from 1 until something is missing. It is correct, it is three lines, and it is the right thing to say out loud first.\n\n' +
      'It is rejected for one reason only: the O(n) Set violates the constant-space requirement. State it, name why it fails, then build up to the in-place version — jumping straight to swaps reads as memorised rather than reasoned.',
    complexity: { time: 'O(n)', space: 'O(n)', verdict: 'Correct, fails the space bound' },
    pseudocode: [
      'present = new Set(nums)',
      'for v from 1 to n+1:',
      '  if not present.has(v): return v',
    ],
    example: { input: '[3, 4, -1, 1]', output: '2' },
    steps: [
      { title: 'new Set reads 3 → add. Set: {3}.', pseudoLine: 0,
        set: firstMissingPositiveSet([3], 3) },
      { title: 'Reads 4 → add. Set: {3, 4}.', pseudoLine: 0,
        set: firstMissingPositiveSet([3, 4], 4) },
      { title: 'Reads −1 → add. Negatives go in too; they simply never get asked about.', pseudoLine: 0,
        set: firstMissingPositiveSet([3, 4, -1], -1) },
      { title: 'Reads 1 → add. present = {3, 4, −1, 1}.', pseudoLine: 0,
        set: firstMissingPositiveSet([3, 4, -1, 1], 1) },
      { title: 'v = 1: present.has(1) is true → keep counting.', pseudoLine: 2,
        set: firstMissingPositiveSet([3, 4, -1, 1], 1, 'hit'),
        computation: { label: 'present.has(1)', lhs: 'true', op: '→', rhs: 'next v' } },
      { title: 'v = 2: present.has(2) is false → return 2.', pseudoLine: 2,
        set: firstMissingPositiveSet([3, 4, -1, 1]),
        computation: { label: 'present.has(2)', lhs: 'false', op: '→', rhs: 'return 2' },
        result: { found: true, value: '2' } },
    ],
    tradeoffs: 'The loop bound must be n + 1, not n. If the array holds exactly 1..n then every v up to n is present and the answer is n + 1 — stop at n and you fall out of the loop with nothing to return.',
  }],
};

// ====================================================================

// Missing Term frame: [2, 5, 8, 14] with lo / hi / mid drawn on it.
const MISSING_TERM_SEQ = [2, 5, 8, 14];
const missingTermInArithmeticSequenceFrame = (lo: number, hi: number, mid = -1): ArraySnapshot => ({
  cells: MISSING_TERM_SEQ.map((v, idx) => ({
    value: v,
    highlight: idx === mid ? 'compare' as const : idx < lo || idx > hi ? undefined : 'i' as const,
  })),
  pointers: [
    ...(lo === hi ? [{ index: lo, label: 'lo=hi', color: 'red' as const }]
      : [{ index: lo, label: 'lo', color: 'red' as const }, { index: hi, label: 'hi', color: 'emerald' as const }]),
    ...(mid >= 0 ? [{ index: mid, label: 'mid', color: 'amber' as const }] : []),
  ],
});

const missingTermInArithmeticSequence: Explanation = {
  problem: 'Missing Term in Arithmetic Sequence',
  problemStatement: 'An arithmetic sequence has had one middle term removed. Given the remaining terms in order, find the missing one.',
  approaches: [{
    id: 'binary-search',
    name: 'Binary Search for the Break',
    badge: 'best',
    intuition:
      '**First recover the step.** The array holds n terms and the complete sequence held n + 1, so the span from first to last is cut into n equal gaps: step = (last - first) / n.\n\n' +
      '**Then notice the predicate is monotonic.** Before the gap, every term sits exactly where it should: seq[i] === first + i * step. After the gap, every term is shifted along by one step, so the test fails and keeps failing. A condition that flips once and never flips back is precisely what binary search needs — so you can find the break without reading the whole array.\n\n' +
      '• seq[mid] is where it should be: the break is to the right, so lo = mid + 1.\n' +
      '• seq[mid] is shifted: the break is at mid or to its left, so hi = mid.\n' +
      'When lo meets hi, that index is the first shifted slot, and the missing term is what belonged there.\n\n' +
      '**The clarifying question to ask out loud:** are the first and last terms guaranteed present? They must be, or the span is wrong and the step is unrecoverable. [2, 5, 8] is a complete sequence and a broken one at the same time, and nothing in the data separates them.',
    complexity: { time: 'O(log n)', space: 'O(1)', verdict: 'Best' },
    pseudocode: [
      'step = (seq[n-1] - seq[0]) / n',
      'lo = 0, hi = n - 1',
      'while lo < hi:',
      '  mid = (lo + hi) / 2',
      '  if seq[mid] == seq[0] + mid * step: lo = mid + 1',
      '  else: hi = mid',
      'return seq[0] + lo * step',
    ],
    example: { input: '[2, 5, 8, 14]', output: '11' },
    steps: [
      { title: '4 terms remain, so the full sequence had 5 and the span is cut into 4 gaps: step = (14 - 2) / 4 = 3.', pseudoLine: 0,
        array: { cells: [{ value: 2, highlight: 'found' }, { value: 5 }, { value: 8 }, { value: 14, highlight: 'found' }] },
        computation: { label: 'step', lhs: '14 - 2', op: '/', rhs: '4', result: '3' } },
      { title: 'lo = 0, hi = 3. The first shifted index is somewhere in [0, 3].', pseudoLine: 1,
        array: missingTermInArithmeticSequenceFrame(0, 3) },
      { title: 'lo=0, hi=3 → mid = 1. Expected 2 + 1·3 = 5, and seq[1] is 5: intact → lo = 2.', pseudoLine: 4,
        detail: 'mid rounds down: (0 + 3) / 2 = 1.5 becomes 1.',
        array: missingTermInArithmeticSequenceFrame(0, 3, 1),
        computation: { label: 'seq[0] + mid · step', lhs: '2 + 1·3', result: '5 = seq[1] ✓ → lo = 2' } },
      { title: 'lo=2, hi=3 → mid = 2. Expected 2 + 2·3 = 8, and seq[2] is 8: intact → lo = 3.', pseudoLine: 4,
        array: missingTermInArithmeticSequenceFrame(2, 3, 2),
        computation: { label: 'seq[0] + mid · step', lhs: '2 + 2·3', result: '8 = seq[2] ✓ → lo = 3' } },
      { title: 'lo = hi = 3, so the loop stops: index 3 is the first shifted slot. The missing term is 2 + 3·3 = 11.', pseudoLine: 6,
        detail: 'seq[3] is 14, one step past the 11 that should have been there, which confirms the break.',
        array: missingTermInArithmeticSequenceFrame(3, 3),
        computation: { label: 'seq[0] + lo · step', lhs: '2 + 3·3', result: '11' },
        result: { found: true, value: '11' } },
    ],
    tradeoffs:
      'Careful with a fractional step: seq[0] + i * step can miss its target by a floating-point rounding error, and the equality test then lies about where the break is. For non-integer terms prefer the sum approach, which never compares two computed floats.',
  },
  {
    id: 'sum',
    name: 'Sum of the Complete Sequence',
    badge: 'alternative',
    intuition:
      'An arithmetic sequence of m terms sums to m · (first + last) / 2 — the average term times the count. The complete sequence had n + 1 terms running between the same two endpoints you were handed, so you can compute what the total should have been and subtract what is actually there. The difference is the missing term.\n\n' +
      'It never divides by the step and never compares two computed values, which makes it the robust choice when the terms are not integers.',
    complexity: { time: 'O(n)', space: 'O(1)', verdict: 'Shortest and safest' },
    pseudocode: [
      'complete = (n + 1) * (seq[0] + seq[n-1]) / 2',
      'actual = 0',
      'for x in seq: actual += x',
      'return complete - actual',
    ],
    example: { input: '[2, 5, 8, 14]', output: '11' },
    steps: [
      { title: 'The complete sequence had 5 terms from 2 to 14, so it summed to 5 · 16 / 2 = 40.', pseudoLine: 0,
        array: { cells: [{ value: 2, highlight: 'found' }, { value: 5 }, { value: 8 }, { value: 14, highlight: 'found' }] },
        computation: { label: 'complete', lhs: '5 · (2 + 14)', op: '/', rhs: '2', result: '40' } },
      { title: 'x = 2: actual = 0 + 2 = 2.', pseudoLine: 2,
        array: { cells: MISSING_TERM_SEQ.map((v, idx) => ({ value: v, highlight: idx === 0 ? 'i' as const : undefined })), pointers: [{ index: 0, label: 'x', color: 'red' }] },
        computation: { label: 'actual += x', lhs: '0 + 2', result: '2' } },
      { title: 'x = 5: actual = 2 + 5 = 7.', pseudoLine: 2,
        array: { cells: MISSING_TERM_SEQ.map((v, idx) => ({ value: v, highlight: idx === 1 ? 'i' as const : undefined })), pointers: [{ index: 1, label: 'x', color: 'red' }] },
        computation: { label: 'actual += x', lhs: '2 + 5', result: '7' } },
      { title: 'x = 8: actual = 7 + 8 = 15.', pseudoLine: 2,
        array: { cells: MISSING_TERM_SEQ.map((v, idx) => ({ value: v, highlight: idx === 2 ? 'i' as const : undefined })), pointers: [{ index: 2, label: 'x', color: 'red' }] },
        computation: { label: 'actual += x', lhs: '7 + 8', result: '15' } },
      { title: 'x = 14: actual = 15 + 14 = 29.', pseudoLine: 2,
        array: { cells: MISSING_TERM_SEQ.map((v, idx) => ({ value: v, highlight: idx === 3 ? 'i' as const : undefined })), pointers: [{ index: 3, label: 'x', color: 'red' }] },
        computation: { label: 'actual += x', lhs: '15 + 14', result: '29' } },
      { title: 'The gap between them is the term that was removed: 40 − 29 = 11.', pseudoLine: 3,
        computation: { label: 'complete − actual', lhs: '40', op: '−', rhs: '29', result: '11' },
        result: { found: true, value: '11' } },
    ],
    tradeoffs: 'Reads the whole array, so O(n) rather than O(log n). That only matters if the array is huge and you were handed it lazily; if it is already in memory the difference is academic and this version is far harder to get wrong.',
  }],
};
// ====================================================================

// Array frame builder shared by the walkthroughs from Move Zeros down to
// Trapping Rain Water: plain cell values, optional per-index highlights, and
// optional [index, label, colour] pointers drawn under the cells.
const moveZerosFrame = (
  values: (string | number)[],
  marks: Partial<Record<number, Highlight>> = {},
  pointers: [number, string, NonNullable<ArraySnapshot['pointers']>[number]['color']][] = [],
): ArraySnapshot => ({
  cells: values.map((value, idx) => {
    const highlight = marks[idx];
    return highlight ? { value, highlight } : { value };
  }),
  ...(pointers.length > 0 ? { pointers: pointers.map(([index, label, color]) => ({ index, label, color })) } : {}),
});

const moveZeros: Explanation = {
  problem: 'Move Zeros',
  problemStatement: 'Move all zeros to the end of an array, in place, preserving the relative order of non-zero elements.',
  approaches: [{
    id: 'write-pointer',
    name: 'Write Pointer (Two Pointer)',
    badge: 'best',
    intuition:
      "**Compact the non-zeros to the front, then paint the tail with zeros.**\n\n" +
      "Two indexes walk the same array:\n" +
      "• `r` (read) visits every cell, left to right.\n" +
      "• `w` (write) is the next slot a non-zero should land in.\n" +
      "• When `arr[r]` is non-zero, copy it to `arr[w]` and move `w` one right. A zero is simply not copied.\n\n" +
      "**Why order is kept:** non-zeros are copied in the order `r` meets them, and `w` never passes `r`, so a copy never overwrites a value that has not been read yet. After the pass, every slot from `w` to the end holds a stale value, and the second loop writes zeros there.",
    complexity: { time: 'O(n)', space: 'O(1)', verdict: 'Canonical' },
    pseudocode: [
      'w = 0',
      'for r from 0 to n-1:',
      '  if arr[r] !== 0: arr[w++] = arr[r]',
      'while w < n: arr[w++] = 0',
    ],
    example: { input: '[0, 1, 0, 3, 12]', output: '[1, 3, 12, 0, 0]' },
    steps: [
      { title: 'r=0: arr[0] is 0 → not copied. w stays at 0.', pseudoLine: 2,
        detail: 'w only moves when a non-zero is written, so it now points at the first slot a non-zero should fill.',
        array: moveZerosFrame([0, 1, 0, 3, 12], { 0: 'i' }, [[0, 'w', 'emerald'], [0, 'r', 'red']]) },
      { title: 'r=1: arr[1] is 1 → copy to arr[0], w → 1.', pseudoLine: 2,
        detail: 'Index 1 still shows the old 1. It is a stale copy now: a later write or the zero-fill will cover it.',
        array: moveZerosFrame([1, 1, 0, 3, 12], { 0: 'found', 1: 'i' }, [[1, 'w', 'emerald'], [1, 'r', 'red']]) },
      { title: 'r=2: arr[2] is 0 → not copied. w stays at 1.', pseudoLine: 2,
        array: moveZerosFrame([1, 1, 0, 3, 12], { 2: 'i' }, [[1, 'w', 'emerald'], [2, 'r', 'red']]) },
      { title: 'r=3: arr[3] is 3 → copy to arr[1], w → 2.', pseudoLine: 2,
        array: moveZerosFrame([1, 3, 0, 3, 12], { 1: 'found', 3: 'i' }, [[2, 'w', 'emerald'], [3, 'r', 'red']]) },
      { title: 'r=4: arr[4] is 12 → copy to arr[2], w → 3. The read loop ends.', pseudoLine: 2,
        detail: 'All three non-zeros now sit in indexes 0–2 in their original order. Indexes 3 and 4 hold stale copies (3 and 12).',
        array: moveZerosFrame([1, 3, 12, 3, 12], { 2: 'found', 4: 'i' }, [[3, 'w', 'emerald'], [4, 'r', 'red']]) },
      { title: 'Fill: w=3 < 5 → arr[3] = 0, w → 4.', pseudoLine: 3,
        array: moveZerosFrame([1, 3, 12, 0, 12], { 3: 'new' }, [[4, 'w', 'emerald']]) },
      { title: 'Fill: w=4 < 5 → arr[4] = 0, w → 5. Now w = n, so the fill stops.', pseudoLine: 3,
        array: moveZerosFrame([1, 3, 12, 0, 0], { 3: 'new', 4: 'new' }),
        result: { found: true, value: '[1, 3, 12, 0, 0]' } },
    ],
    tradeoffs: 'Single-pass swap variant `if (arr[r]) [arr[w], arr[r]] = [arr[r], arr[w]], w++` skips the second loop but does redundant swaps when w === r. The write-pointer + zero-fill is the cleanest pattern.',
  },
  {
    id: 'single-swap',
    name: 'Single-Pass Swap (One Loop)',
    badge: 'alternative',
    intuition:
      "**Same two pointers, one loop: swap instead of copy.** Every time `r` finds a non-zero, swap it with `arr[w]` and move `w` right.\n\n" +
      "• `arr[r]` is 0: do nothing.\n" +
      "• `arr[r]` is non-zero: swap `arr[w]` and `arr[r]`, then `w++`.\n\n" +
      "**Why the zeros end up at the back:** everything between `w` and `r` is a zero that has been passed over. A swap moves the non-zero to the front of that zero run and pushes one zero to its back, so no fill loop is needed.\n\n" +
      "The one cost: until the first zero is seen, `w === r` and each swap exchanges a cell with itself. Both versions are O(n).",
    complexity: { time: 'O(n)', space: 'O(1)', verdict: 'Slightly less code; same complexity' },
    pseudocode: [
      'w = 0',
      'for r from 0 to n-1:',
      '  if arr[r] !== 0:',
      '    [arr[w], arr[r]] = [arr[r], arr[w]]',
      '    w++',
    ],
    example: { input: '[0, 1, 0, 3, 12]', output: '[1, 3, 12, 0, 0]' },
    steps: [
      { title: 'r=0: arr[0] is 0 → no swap. w stays at 0.', pseudoLine: 2,
        array: moveZerosFrame([0, 1, 0, 3, 12], { 0: 'i' }, [[0, 'w', 'emerald'], [0, 'r', 'red']]) },
      { title: 'r=1: 1 is non-zero → swap arr[0] ↔ arr[1] → [1,0,0,3,12]. w → 1.', pseudoLine: 3,
        detail: 'The 1 jumps over the zero in front of it, and that zero lands where the 1 was.',
        array: moveZerosFrame([1, 0, 0, 3, 12], { 0: 'found', 1: 'i' }, [[1, 'w', 'emerald'], [1, 'r', 'red']]) },
      { title: 'r=2: arr[2] is 0 → no swap. w stays at 1.', pseudoLine: 2,
        array: moveZerosFrame([1, 0, 0, 3, 12], { 2: 'i' }, [[1, 'w', 'emerald'], [2, 'r', 'red']]) },
      { title: 'r=3: 3 is non-zero → swap arr[1] ↔ arr[3] → [1,3,0,0,12]. w → 2.', pseudoLine: 3,
        array: moveZerosFrame([1, 3, 0, 0, 12], { 1: 'found', 3: 'i' }, [[2, 'w', 'emerald'], [3, 'r', 'red']]) },
      { title: 'r=4: 12 is non-zero → swap arr[2] ↔ arr[4] → [1,3,12,0,0]. w → 3. Loop ends.', pseudoLine: 3,
        array: moveZerosFrame([1, 3, 12, 0, 0], { 2: 'found', 4: 'i' }, [[3, 'w', 'emerald'], [4, 'r', 'red']]),
        result: { found: true, value: '[1, 3, 12, 0, 0]' } },
    ],
    tradeoffs: 'Slightly more elegant. The two-pass version separates concerns (compact, then fill) which some readers find clearer.',
  }],
};

