const memoize: Explanation = {
  problem: 'Memoize',
  problemStatement: 'Wrap any pure function so repeated calls with the same arguments return cached results.',
  approaches: [{
    id: 'map-cache',
    name: 'Map<key, value> Cache',
    badge: 'best',
    intuition:
      "**Remember every answer, keyed by the arguments that produced it.** Memoisation means caching each result so the same input is computed only once. It is safe only for pure functions, whose output depends on nothing but their arguments.\n\n" +
      "• Turn the argument list into a string key with `JSON.stringify(args)`, so `[5]` always maps to the same key.\n" +
      "• Key not in the cache (a miss): call the real function and store its result.\n" +
      "• Key in the cache (a hit): skip the function and return the stored result.\n\n" +
      "**The catch:** `JSON.stringify` cannot tell apart values it cannot serialise (functions, `undefined`) and throws on circular objects, so this key only suits plain data.",
    complexity: { time: 'O(1) per cached hit', space: 'O(unique-call-count)', verdict: 'Canonical' },
    pseudocode: [
      'function memoize(fn):',
      '  cache = new Map()',
      '  return (...args) =>',
      '    key = JSON.stringify(args)',
      '    if !cache.has(key): cache.set(key, fn(...args))',
      '    return cache.get(key)',
    ],
    example: { input: 'm = memoize(slowSquare); m(5); m(5); m(7)', output: '25, 25 (from cache), 49' },
    steps: [
      { title: 'memoize(slowSquare): create an empty cache and return the wrapper m.', pseudoLine: 1,
        map: { entries: [] } },
      { title: 'm(5): key = JSON.stringify([5]) = "[5]".', pseudoLine: 3,
        computation: { label: 'key', lhs: 'JSON.stringify([5])', result: '"[5]"' },
        map: { entries: [] } },
      { title: '"[5]" is not cached (miss) → run slowSquare(5) = 25 and store it.', pseudoLine: 4,
        lookupOutcome: { kind: 'miss', key: '[5]' },
        map: { entries: [{ key: '[5]', value: 25, highlight: 'new' }] } },
      { title: 'Return cache.get("[5]") → 25. slowSquare has run once.', pseudoLine: 5,
        map: { entries: [{ key: '[5]', value: 25 }] },
        computation: { label: 'm(5)', result: '25' } },
      { title: 'm(5) again: key "[5]" is cached (hit) → slowSquare is skipped.', pseudoLine: 4,
        lookupOutcome: { kind: 'hit', key: '[5]', at: 'cache' },
        map: { entries: [{ key: '[5]', value: 25, highlight: 'hit' }] } },
      { title: 'Return 25 from the cache. slowSquare still has run only once.', pseudoLine: 5,
        map: { entries: [{ key: '[5]', value: 25, highlight: 'hit' }] },
        computation: { label: 'm(5)', result: '25 (cached)' } },
      { title: 'm(7): key "[7]" is not cached (miss) → run slowSquare(7) = 49 and store it.', pseudoLine: 4,
        lookupOutcome: { kind: 'miss', key: '[7]' },
        map: { entries: [{ key: '[5]', value: 25 }, { key: '[7]', value: 49, highlight: 'new' }] } },
      { title: 'Return 49. Three calls, two real computations.', pseudoLine: 5,
        map: { entries: [{ key: '[5]', value: 25 }, { key: '[7]', value: 49 }] },
        result: { found: true, value: '25, 25, 49' } },
    ],
    tradeoffs: '`JSON.stringify` keys break for unserializable args (functions, circular). `WeakMap` keyed by argument identity works for object args and lets entries get GCed. LRU-bounded cache prevents unbounded memory growth.',
  },
  {
    id: 'weakmap',
    name: 'WeakMap Cache (Object Args)',
    badge: 'alternative',
    intuition:
      "**When the argument is an object, key the cache by the object itself.** A `WeakMap` uses object identity (the same object in memory) as the key, so no string key is needed and unserialisable values are no problem.\n\n" +
      "• Same object passed again: hit.\n" +
      "• A different object with the same contents: a different key, so a miss. That is identity, not value, equality.\n\n" +
      "**Why weak:** a `WeakMap` does not keep its keys alive. Once nothing else references the object, the garbage collector may free it together with its cache entry, so the cache cannot leak memory.",
    complexity: { time: 'O(1) per call', space: 'O(unique-objects)', verdict: 'Best for single-object args' },
    pseudocode: [
      'function memoize(fn):',
      '  cache = new WeakMap()',
      '  return (obj) =>',
      '    if (cache.has(obj)): return cache.get(obj)',
      '    result = fn(obj)',
      '    cache.set(obj, result)',
      '    return result',
    ],
    example: { input: 'alice = { name: "Alice" }; m = memoize(u => u.name.toUpperCase()); m(alice); m(alice)', output: '"ALICE" twice; the function runs once' },
    steps: [
      { title: 'memoize(fn): create an empty WeakMap and return the wrapper m.', pseudoLine: 1,
        map: { entries: [] } },
      { title: 'm(alice): the WeakMap has no entry for this object (miss).', pseudoLine: 3,
        lookupOutcome: { kind: 'miss', key: 'alice' },
        map: { entries: [] } },
      { title: 'result = fn(alice) = "ALICE".', pseudoLine: 4,
        computation: { label: 'fn(alice)', lhs: '"Alice".toUpperCase()', result: '"ALICE"' } },
      { title: 'cache.set(alice, "ALICE"): the object itself is the key.', pseudoLine: 5,
        map: { entries: [{ key: 'alice (object)', value: '"ALICE"', highlight: 'new' }] } },
      { title: 'Return "ALICE".', pseudoLine: 6,
        map: { entries: [{ key: 'alice (object)', value: '"ALICE"' }] },
        computation: { label: 'm(alice)', result: '"ALICE"' } },
      { title: 'm(alice) again: same object → hit → return "ALICE" without calling fn.', pseudoLine: 3,
        lookupOutcome: { kind: 'hit', key: 'alice', at: 'WeakMap' },
        map: { entries: [{ key: 'alice (object)', value: '"ALICE"', highlight: 'hit' }] } },
      { title: 'Later, alice = null: the entry can be garbage-collected with the object.', pseudoLine: 1,
        detail: 'No cleanup code is needed. The exact moment is up to the garbage collector, and a WeakMap cannot be iterated, so you never observe a half-collected cache.',
        map: { entries: [{ key: 'alice (unreachable)', value: '"ALICE"' }] },
        note: 'WeakMap holds keys weakly, so the cache never keeps an object alive by itself.',
        result: { found: true, value: '"ALICE" twice (fn ran once)' } },
    ],
    tradeoffs: 'Only works when the cache key is an object (WeakMap requires object keys). For mixed args, layer a regular Map on top: `if (typeof arg === "object") use WeakMap else use Map`.',
  }],
};

