const throttle: Explanation = {
  problem: 'Throttle',
  problemStatement: 'Wrap a function so it runs at most once every `wait` ms. Bursty calls collapse to a steady stream.',
  approaches: [{
    id: 'timestamp',
    name: 'Timestamp-Based',
    badge: 'best',
    intuition:
      "**Remember when the function last ran, and ignore calls that come too soon after.** Throttling means capping how often a function may run: here, at most once per `wait` ms.\n\n" +
      "• On each call, compute `now - last`.\n" +
      "• `now - last >= wait`: enough time has passed → run `fn` and set `last = now`.\n" +
      "• Otherwise: drop the call. It is never run later.\n\n" +
      "**Why `last = 0` makes the first call fire:** `Date.now()` counts milliseconds since 1970, so `now - 0` is enormous. This is a leading-edge throttle: the first call of a burst runs at once.",
    complexity: { time: 'O(1) per call', space: 'O(1)', verdict: 'Canonical leading-edge throttle' },
    pseudocode: [
      'function throttle(fn, wait):',
      '  last = 0',
      '  return (...args) =>',
      '    now = Date.now()',
      '    if now - last >= wait:',
      '      last = now; fn(...args)',
    ],
    example: { input: 'throttle(fn, 200); calls at t=0,50,150,300', output: 'fires at t=0, t=300' },
    steps: [
      { title: 't=0: last is 0 ("never ran"), so now - last is huge ≥ 200 → fire. last = t0.', pseudoLine: 5,
        detail: 'Times here are measured from the first call. In real code now is Date.now(), about 1.7 trillion, so the first call always passes the check.',
        timeline: { events: [{ t: 0, label: 'fire', kind: 'fire' }], windowMs: 200 },
        computation: { label: 'now - last >= wait?', lhs: 'huge >= 200', result: 'yes → fire' } },
      { title: 't=50: 50 - 0 = 50 < 200 → drop the call.', pseudoLine: 4,
        timeline: { events: [{ t: 0, label: 'fire', kind: 'fire' }, { t: 50, label: 'skip', kind: 'skip' }], windowMs: 200 },
        computation: { label: 'now - last >= wait?', lhs: '50 >= 200', result: 'no → skip' } },
      { title: 't=150: 150 - 0 = 150 < 200 → drop the call.', pseudoLine: 4,
        timeline: { events: [{ t: 0, label: 'fire', kind: 'fire' }, { t: 50, label: 'skip', kind: 'skip' }, { t: 150, label: 'skip', kind: 'skip' }], windowMs: 200 },
        computation: { label: 'now - last >= wait?', lhs: '150 >= 200', result: 'no → skip' } },
      { title: 't=300: 300 - 0 = 300 ≥ 200 → fire. last = 300.', pseudoLine: 5,
        detail: 'The next call would have to wait until t=500. The calls at 50 and 150 are gone for good: that is the difference from a trailing throttle.',
        timeline: { events: [{ t: 0, label: 'fire', kind: 'fire' }, { t: 50, label: 'skip', kind: 'skip' }, { t: 150, label: 'skip', kind: 'skip' }, { t: 300, label: 'fire', kind: 'fire' }], windowMs: 200 },
        computation: { label: 'now - last >= wait?', lhs: '300 >= 200', result: 'yes → fire' },
        result: { found: true, value: 'fires at t=0 and t=300' } },
    ],
    tradeoffs: 'Trailing throttle (fire AFTER the wait window with the last args) is friendlier for "scroll position" — you do not lose the final position. Both-edges variant fires on first AND last call. Pick by use case: animations want trailing; rate-limiting wants leading.',
  },
  {
    id: 'trailing',
    name: 'Trailing-Edge Throttle (Catches Final Args)',
    badge: 'alternative',
    intuition:
      "**Run once at the end of each window, with the most recent arguments.** The leading-edge version drops the calls inside the window, including the last one. For scroll position or autosave the last value is the one that matters.\n\n" +
      "• Every call overwrites `latestArgs`.\n" +
      "• If no timer is pending, start one for `wait` ms. Calls while a timer is pending only update `latestArgs`.\n" +
      "• When the timer fires, call `fn(...latestArgs)` and set `timer = null`, so the next call starts a new window.\n\n" +
      "**The key detail:** the timer callback reads `latestArgs` when it runs, not when it was scheduled, so it always sees the newest call.",
    complexity: { time: 'O(1) per call', space: 'O(1)', verdict: 'For scroll/autosave/animation' },
    pseudocode: [
      'function throttleTrailing(fn, wait):',
      '  let timer = null, latestArgs',
      '  return (...args) =>',
      '    latestArgs = args',
      '    if (timer === null):',
      '      timer = setTimeout(() => { fn(...latestArgs); timer = null }, wait)',
    ],
    example: { input: 'wait=200; calls at t=0,50,150,300', output: 'fires at t=200 (args from t=150) and t=500 (args from t=300)' },
    steps: [
      { title: 't=0: latestArgs = args@0. timer is null → schedule a fire at t=200.', pseudoLine: 5,
        timeline: { events: [{ t: 0, label: 'call', kind: 'input' }, { t: 200, label: 'timer', kind: 'pending' }], windowMs: 200 } },
      { title: 't=50: latestArgs = args@50. A timer is pending → nothing else to do.', pseudoLine: 3,
        timeline: { events: [{ t: 0, label: 'call', kind: 'input' }, { t: 50, label: 'call', kind: 'input' }, { t: 200, label: 'timer', kind: 'pending' }], windowMs: 200 } },
      { title: 't=150: latestArgs = args@150. The timer is still pending.', pseudoLine: 3,
        timeline: { events: [{ t: 0, label: 'call', kind: 'input' }, { t: 50, label: 'call', kind: 'input' }, { t: 150, label: 'call', kind: 'input' }, { t: 200, label: 'timer', kind: 'pending' }], windowMs: 200 } },
      { title: 't=200: the timer calls fn with latestArgs, which are the args from t=150. timer = null.', pseudoLine: 5,
        detail: 'The args from t=0 and t=50 were overwritten before the timer ran, so only the newest call reaches fn.',
        timeline: { events: [{ t: 0, label: 'call', kind: 'input' }, { t: 50, label: 'call', kind: 'input' }, { t: 150, label: 'call', kind: 'input' }, { t: 200, label: 'fire@150', kind: 'fire' }], windowMs: 200 } },
      { title: 't=300: latestArgs = args@300. timer is null again → schedule a fire at t=500.', pseudoLine: 5,
        timeline: { events: [{ t: 0, label: 'call', kind: 'input' }, { t: 150, label: 'call', kind: 'input' }, { t: 200, label: 'fire@150', kind: 'fire' }, { t: 300, label: 'call', kind: 'input' }, { t: 500, label: 'timer', kind: 'pending' }], windowMs: 200 } },
      { title: 't=500: the timer fires fn with the args from t=300. timer = null.', pseudoLine: 5,
        timeline: { events: [{ t: 0, label: 'call', kind: 'input' }, { t: 150, label: 'call', kind: 'input' }, { t: 200, label: 'fire@150', kind: 'fire' }, { t: 300, label: 'call', kind: 'input' }, { t: 500, label: 'fire@300', kind: 'fire' }], windowMs: 200 },
        result: { found: true, value: 'fires at t=200 (args@150) and t=500 (args@300)' } },
    ],
    tradeoffs: 'Trailing for scroll/autosave/animation. Leading for rate limits where the first signal matters. Both-edges (`{ leading: true, trailing: true }`) is what lodash defaults to — fires twice per burst, once on the leading edge and once with the latest args at the trailing edge.',
  }],
};

