const eventEmitter: Explanation = {
  problem: 'EventEmitter',
  problemStatement: 'Implement on, off, and emit. on(event, fn) registers; off removes; emit(event, ...args) fires every registered handler in order.',
  approaches: [{
    id: 'map-set',
    name: 'Map<event, Set<fn>>',
    badge: 'best',
    intuition:
      "**Keep a list of handlers per event name, and call them all on emit.** The store is a `Map` from event name to a `Set` of handler functions.\n\n" +
      "• `on(name, fn)`: create the set on first use, then `add(fn)`.\n" +
      "• `off(name, fn)`: `delete(fn)` from that set, which is O(1).\n" +
      "• `emit(name, ...args)`: call every handler in the set with the same arguments.\n\n" +
      "**Why a Set:** registering the same function twice has no effect, and a `Set` iterates in insertion order, so handlers run in the order they were added.",
    complexity: { time: 'O(1) on/off, O(n) emit', space: 'O(handlers)', verdict: 'Canonical' },
    pseudocode: [
      'class EventEmitter:',
      '  events = new Map()',
      '  on(name, fn): get-or-create set, add fn',
      '  off(name, fn): set.delete(fn)',
      '  emit(name, ...args): for fn in set: fn(...args)',
    ],
    example: { input: 'on("greet", a); on("greet", b); emit("greet", "hi")', output: 'a("hi"), b("hi")' },
    steps: [
      { title: 'new EventEmitter(): the events map is empty.', pseudoLine: 1,
        map: { entries: [] } },
      { title: 'on("greet", a): no set for "greet" yet → create it, add a.', pseudoLine: 2,
        map: { entries: [{ key: 'greet', value: 'Set{a}', highlight: 'new' }] } },
      { title: 'on("greet", b): the set exists → add b. Set{a, b}.', pseudoLine: 2,
        map: { entries: [{ key: 'greet', value: 'Set{a, b}', highlight: 'hit' }] } },
      { title: 'emit("greet", "hi"): first handler in the set → a("hi").', pseudoLine: 4,
        map: { entries: [{ key: 'greet', value: 'Set{a, b}', highlight: 'hit' }] },
        array: moveZerosFrame(['a', 'b'], { 0: 'i' }, [[0, 'fn', 'red']]),
        computation: { label: 'call', lhs: 'a("hi")' } },
      { title: 'Second handler → b("hi"). The set is exhausted, so emit returns.', pseudoLine: 4,
        map: { entries: [{ key: 'greet', value: 'Set{a, b}' }] },
        array: moveZerosFrame(['a', 'b'], { 0: 'found', 1: 'i' }, [[1, 'fn', 'red']]),
        computation: { label: 'call', lhs: 'b("hi")' },
        result: { found: true, value: 'a("hi"), then b("hi")' } },
    ],
    tradeoffs: 'Array variant `Map<event, Array<fn>>` allows duplicates and preserves order more obviously, but `off` becomes O(n). Once-handlers wrap the original to remove itself after firing — common extension.',
  },
  {
    id: 'array',
    name: 'Map<event, Array<fn>> (Order-Visible)',
    badge: 'alternative',
    intuition:
      "**Same map, but each event holds an array of handlers instead of a set.** Two consequences:\n\n" +
      "• The same handler can be registered twice, and then it fires twice. Sometimes that is wanted, often it is a bug.\n" +
      "• `off` has to find the handler with `indexOf` and `splice` it out, which is O(n) instead of O(1).\n\n" +
      "**Why pick it anyway:** it mirrors Node's built-in `EventEmitter`, which also stores arrays and allows duplicates.",
    complexity: { time: 'O(1) on, O(n) off, O(n) emit', space: 'O(handlers)', verdict: 'When duplicates allowed or to mirror Node EventEmitter' },
    pseudocode: [
      'class EventEmitter:',
      '  events = new Map()',
      '  on(name, fn): get-or-create array, push fn',
      '  off(name, fn): array.indexOf(fn) → splice',
      '  emit(name, ...args): for fn of array: fn(...args)',
    ],
    example: { input: 'on("greet", a); on("greet", a); emit("greet", "hi")', output: 'a("hi") fires TWICE' },
    steps: [
      { title: 'on("greet", a): no array yet → create it and push a. [a].', pseudoLine: 2,
        map: { entries: [{ key: 'greet', value: '[a]', highlight: 'new' }] } },
      { title: 'on("greet", a) again: push a again → [a, a].', pseudoLine: 2,
        map: { entries: [{ key: 'greet', value: '[a, a]', highlight: 'hit' }] },
        note: 'A Set would have ignored the second add and stayed {a}.' },
      { title: 'emit("greet", "hi"): index 0 → a("hi").', pseudoLine: 4,
        map: { entries: [{ key: 'greet', value: '[a, a]' }] },
        array: moveZerosFrame(['a', 'a'], { 0: 'i' }, [[0, 'fn', 'red']]),
        computation: { label: 'call', lhs: 'a("hi")', result: 'call #1' } },
      { title: 'Index 1 → a("hi") again. The same handler ran twice.', pseudoLine: 4,
        map: { entries: [{ key: 'greet', value: '[a, a]' }] },
        array: moveZerosFrame(['a', 'a'], { 0: 'found', 1: 'i' }, [[1, 'fn', 'red']]),
        computation: { label: 'call', lhs: 'a("hi")', result: 'call #2' },
        result: { found: true, value: 'a("hi") × 2' } },
    ],
    tradeoffs: 'Mirror Node\'s native `EventEmitter` (which uses arrays). For dedup-by-default behavior, use Set. For "register once, fire once even if registered twice" semantics, Set wins.',
  }],
};

