// [1,3,5,7,9,11] with lo / mid / hi drawn; cells outside [lo, hi] are ruled out.
const binarySearchFrame = (lo: number, mid: number, hi: number, found = false): ArraySnapshot =>
  moveZerosFrame([1, 3, 5, 7, 9, 11], { [mid]: found ? 'found' : 'i' }, [[lo, 'lo', 'emerald'], [mid, 'mid', 'indigo'], [hi, 'hi', 'amber']]);

const binarySearch: Explanation = {
  problem: 'Binary Search',
  problemStatement: 'Find the index of target in a sorted array, or -1 if absent. Run in O(log n).',
  approaches: [{
    id: 'iterative',
    name: 'Iterative Two-Pointer',
    badge: 'best',
    intuition:
      "**Look at the middle and throw away the half that cannot contain the target.** This only works because the array is sorted.\n\n" +
      "Keep the search range `low … high` (both inclusive). Each round, `mid = floor((low + high) / 2)`:\n" +
      "• `arr[mid] === target`: found, return `mid`.\n" +
      "• `arr[mid] < target`: the target can only be to the right → `low = mid + 1`.\n" +
      "• `arr[mid] > target`: it can only be to the left → `high = mid - 1`.\n" +
      "If the range becomes empty (`low > high`), the target is absent: return -1.\n\n" +
      "**Why O(log n):** each round halves the range, so an array of a million elements needs at most about 20 rounds.",
    complexity: { time: 'O(log n)', space: 'O(1)', verdict: 'Canonical' },
    pseudocode: [
      'low = 0, high = n - 1',
      'while low <= high:',
      '  mid = floor((low + high) / 2)',
      '  if arr[mid] === target: return mid',
      '  if arr[mid] < target: low = mid + 1',
      '  else: high = mid - 1',
      'return -1',
    ],
    example: { input: '[1,3,5,7,9,11], target=7', output: '3' },
    steps: [
      { title: 'low=0, high=5 → mid=2. arr[2]=5 < 7 → the target is to the right: low = 3.', pseudoLine: 4,
        array: binarySearchFrame(0, 2, 5),
        computation: { label: 'arr[mid] vs target', lhs: '5', op: '<', rhs: '7', result: 'low = mid + 1 = 3' } },
      { title: 'low=3, high=5 → mid=4. arr[4]=9 > 7 → the target is to the left: high = 3.', pseudoLine: 5,
        detail: 'Indexes 0–2 were ruled out in the previous round, so only 3–5 remain.',
        array: binarySearchFrame(3, 4, 5),
        computation: { label: 'arr[mid] vs target', lhs: '9', op: '>', rhs: '7', result: 'high = mid - 1 = 3' } },
      { title: 'low=3, high=3 → mid=3. arr[3]=7 === 7 → return 3.', pseudoLine: 3,
        array: binarySearchFrame(3, 3, 3, true),
        computation: { label: 'arr[mid] vs target', lhs: '7', op: '===', rhs: '7', result: 'found' },
        result: { found: true, value: '3' } },
    ],
    tradeoffs: 'Off-by-one is the classic bug: write the loop condition as `low <= high` (inclusive) and update with `mid + 1` / `mid - 1`. Use `mid = low + Math.floor((high - low) / 2)` to avoid integer overflow in non-JS languages.',
  },
  {
    id: 'recursive',
    name: 'Recursive Binary Search',
    badge: 'alternative',
    intuition:
      "**The same halving, written as a function that calls itself on the half that could contain the target.** `low` and `high` become parameters instead of loop variables.\n\n" +
      "• `low > high`: empty range → return -1 (the base case).\n" +
      "• Match at `mid` → return `mid`.\n" +
      "• Otherwise return the result of searching the right half or the left half.\n\n" +
      "**The cost:** each call adds a stack frame, so space is O(log n). JavaScript engines generally do not perform tail-call optimisation (reusing the frame for a call in return position), so the frames really do pile up. At log₂ n depth that is harmless in practice, but the loop version needs no stack at all.",
    complexity: { time: 'O(log n)', space: 'O(log n) call stack', verdict: 'Cleaner code; risk of stack overflow on huge arrays' },
    pseudocode: [
      'function search(arr, target, low = 0, high = arr.length - 1):',
      '  if low > high: return -1',
      '  mid = (low + high) >> 1',
      '  if arr[mid] === target: return mid',
      '  if arr[mid] < target: return search(arr, target, mid + 1, high)',
      '  return search(arr, target, low, mid - 1)',
    ],
    example: { input: '[1,3,5,7,9,11], target=7', output: '3' },
    steps: [
      { title: 'search(0, 5): mid=2, arr[2]=5 < 7 → return search(3, 5).', pseudoLine: 4,
        detail: '(low + high) >> 1 shifts the bits right by one, which is floor division by 2 for non-negative integers.',
        array: binarySearchFrame(0, 2, 5),
        callStack: { frames: [{ call: 'search(0, 5)', status: 'active' }] } },
      { title: 'search(3, 5): mid=4, arr[4]=9 > 7 → return search(3, 3).', pseudoLine: 5,
        array: binarySearchFrame(3, 4, 5),
        callStack: { frames: [{ call: 'search(0, 5)', status: 'pending' }, { call: 'search(3, 5)', status: 'active' }] } },
      { title: 'search(3, 3): mid=3, arr[3]=7 === 7 → return 3.', pseudoLine: 3,
        array: binarySearchFrame(3, 3, 3, true),
        callStack: { frames: [{ call: 'search(0, 5)', status: 'pending' }, { call: 'search(3, 5)', status: 'pending' }, { call: 'search(3, 3)', status: 'returned', returns: '3' }] } },
      { title: 'search(3, 5) returns the 3 it received.', pseudoLine: 5,
        array: binarySearchFrame(3, 3, 3, true),
        callStack: { frames: [{ call: 'search(0, 5)', status: 'pending' }, { call: 'search(3, 5)', status: 'returned', returns: '3' }] } },
      { title: 'search(0, 5) returns 3 to the caller.', pseudoLine: 4,
        array: binarySearchFrame(3, 3, 3, true),
        callStack: { frames: [{ call: 'search(0, 5)', status: 'returned', returns: '3' }] },
        result: { found: true, value: '3' } },
    ],
    tradeoffs: 'Iterative is preferred unless the interviewer explicitly asks for recursion. JS engines do not reliably eliminate tail calls, so deep recursion blows the stack — for n=10⁹, log₂(n) ≈ 30 frames is fine, but most interview engines reject recursion on principle.',
  }],
};

