// "MCMXCIV" with the current index i drawn (red) and the neighbour it is compared with (blue).
const ROMAN_TO_INTEGER_S = ['M', 'C', 'M', 'X', 'C', 'I', 'V'];
const romanToIntegerFrame = (i: number, compareWith?: number): ArraySnapshot =>
  moveZerosFrame(
    ROMAN_TO_INTEGER_S,
    compareWith === undefined ? { [i]: 'i' } : { [i]: 'i', [compareWith]: 'compare' },
    [[i, 'i', 'red']],
  );

const romanToInteger: Explanation = {
  problem: 'Roman to Integer',
  problemStatement: 'Convert a Roman numeral string to an integer. Handle subtractive cases (IV=4, IX=9, etc.) by checking if the next symbol is larger.',
  approaches: [{
    id: 'peek-next',
    name: 'Peek Next, Subtract on Mismatch',
    badge: 'best',
    intuition:
      "**Normally Roman symbols are added. A symbol is subtracted only when a larger one comes right after it.** That is the subtractive notation: IV = 5 − 1, CM = 1000 − 100.\n\n" +
      "Walk left to right and peek at the next symbol:\n" +
      "• `val[s[i]] < val[s[i+1]]`: this symbol is the small half of a subtractive pair → `total -= val[s[i]]`.\n" +
      "• Otherwise (bigger or equal, or the last symbol) → `total += val[s[i]]`.\n\n" +
      "The larger symbol of each pair is then added normally on the next step, so CM contributes −100 + 1000 = 900.",
    complexity: { time: 'O(n)', space: 'O(1)', verdict: 'Canonical' },
    pseudocode: [
      'val = { I:1, V:5, X:10, L:50, C:100, D:500, M:1000 }',
      'total = 0',
      'for i from 0 to n-1:',
      '  if i+1 < n and val[s[i]] < val[s[i+1]]: total -= val[s[i]]',
      '  else: total += val[s[i]]',
      'return total',
    ],
    example: { input: '"MCMXCIV"', output: '1994' },
    steps: [
      { title: 'i=0: M (1000), next C (100). 1000 is not < 100 → add. total = 1000.', pseudoLine: 4,
        array: romanToIntegerFrame(0, 1),
        computation: { label: 'total', lhs: '0 + 1000', result: '1000' } },
      { title: 'i=1: C (100), next M (1000). 100 < 1000 → subtract. total = 900.', pseudoLine: 3,
        detail: 'C before M is the subtractive pair CM. The M is added on the next step.',
        array: romanToIntegerFrame(1, 2),
        computation: { label: 'total', lhs: '1000 - 100', result: '900' } },
      { title: 'i=2: M (1000), next X (10) → add. total = 1900.', pseudoLine: 4,
        array: romanToIntegerFrame(2, 3),
        computation: { label: 'total', lhs: '900 + 1000', result: '1900' } },
      { title: 'i=3: X (10), next C (100). 10 < 100 → subtract. total = 1890.', pseudoLine: 3,
        array: romanToIntegerFrame(3, 4),
        computation: { label: 'total', lhs: '1900 - 10', result: '1890' } },
      { title: 'i=4: C (100), next I (1) → add. total = 1990.', pseudoLine: 4,
        array: romanToIntegerFrame(4, 5),
        computation: { label: 'total', lhs: '1890 + 100', result: '1990' } },
      { title: 'i=5: I (1), next V (5). 1 < 5 → subtract. total = 1989.', pseudoLine: 3,
        array: romanToIntegerFrame(5, 6),
        computation: { label: 'total', lhs: '1990 - 1', result: '1989' } },
      { title: 'i=6: V (5) is the last symbol, nothing to peek at → add. total = 1994.', pseudoLine: 4,
        detail: 'The i+1 < n check stops the peek from reading past the end of the string.',
        array: romanToIntegerFrame(6),
        computation: { label: 'total', lhs: '1989 + 5', result: '1994' } },
      { title: 'The loop is done → return 1994.', pseudoLine: 5,
        computation: { label: 'M + CM + XC + IV', lhs: '1000 + 900 + 90 + 4', result: '1994' },
        result: { found: true, value: '1994' } },
    ],
    tradeoffs: 'Right-to-left scan with a "running max" is symmetric and avoids the `i+1 < n` bound-check; some find it more readable. Replace-pairs (IV→4, IX→9, …) is fun but slow for long inputs.',
  },
  {
    id: 'right-to-left',
    name: 'Right-to-Left with Running Max',
    badge: 'alternative',
    intuition:
      "**Walk backward and compare each symbol with the largest one already seen to its right.** Keep `maxRight`, the biggest value met so far.\n\n" +
      "• `v >= maxRight`: add it and raise `maxRight` to `v`.\n" +
      "• `v < maxRight`: a bigger symbol sits to its right, so this is the small half of a subtractive pair → subtract it.\n\n" +
      "**Why it works:** in a valid numeral, symbols never increase from left to right except in the subtractive pairs. Walking backward, the only symbols smaller than something already seen are exactly those pairs. No peek-ahead means no `i + 1 < n` bounds check.",
    complexity: { time: 'O(n)', space: 'O(1)', verdict: 'Equally good; symmetric, no peek' },
    pseudocode: [
      'val = { I:1, V:5, X:10, L:50, C:100, D:500, M:1000 }',
      'total = 0, maxRight = 0',
      'for i from n-1 down to 0:',
      '  v = val[s[i]]',
      '  if v >= maxRight: total += v; maxRight = v',
      '  else: total -= v',
      'return total',
    ],
    example: { input: '"MCMXCIV"', output: '1994' },
    steps: [
      { title: 'i=6: V (5) ≥ maxRight 0 → add. total = 5, maxRight = 5.', pseudoLine: 4,
        array: romanToIntegerFrame(6),
        computation: { label: 'total', lhs: '0 + 5', result: '5 (maxRight 5)' } },
      { title: 'i=5: I (1) < maxRight 5 → subtract. total = 4.', pseudoLine: 5,
        detail: 'A bigger symbol (V) is to the right, so this I is the "1 before 5" of IV.',
        array: romanToIntegerFrame(5),
        computation: { label: 'total', lhs: '5 - 1', result: '4 (maxRight 5)' } },
      { title: 'i=4: C (100) ≥ 5 → add. total = 104, maxRight = 100.', pseudoLine: 4,
        array: romanToIntegerFrame(4),
        computation: { label: 'total', lhs: '4 + 100', result: '104 (maxRight 100)' } },
      { title: 'i=3: X (10) < 100 → subtract. total = 94.', pseudoLine: 5,
        array: romanToIntegerFrame(3),
        computation: { label: 'total', lhs: '104 - 10', result: '94 (maxRight 100)' } },
      { title: 'i=2: M (1000) ≥ 100 → add. total = 1094, maxRight = 1000.', pseudoLine: 4,
        array: romanToIntegerFrame(2),
        computation: { label: 'total', lhs: '94 + 1000', result: '1094 (maxRight 1000)' } },
      { title: 'i=1: C (100) < 1000 → subtract. total = 994.', pseudoLine: 5,
        array: romanToIntegerFrame(1),
        computation: { label: 'total', lhs: '1094 - 100', result: '994 (maxRight 1000)' } },
      { title: 'i=0: M (1000) ≥ 1000 → add. total = 1994.', pseudoLine: 4,
        detail: 'Equal counts as "not smaller", which is why MM = 2000 and not 0.',
        array: romanToIntegerFrame(0),
        computation: { label: 'total', lhs: '994 + 1000', result: '1994 (maxRight 1000)' } },
      { title: 'The loop is done → return 1994.', pseudoLine: 6,
        computation: { label: 'total', result: '1994' },
        result: { found: true, value: '1994' } },
    ],
    tradeoffs: 'Same complexity, slightly more elegant — no boundary check, no peek-ahead. Choose by readability preference.',
  }],
};

