const reverseLinkedList: Explanation = {
  problem: 'Reverse Linked List',
  problemStatement: 'Given the head of a singly linked list, reverse it in place and return the new head.',
  approaches: [{
    id: 'three-pointer',
    name: 'Iterative Three-Pointer',
    badge: 'best',
    intuition:
      "**Walk the list once and turn every `next` arrow around.** A singly linked list is a chain of nodes where each node knows only the node after it (`next`).\n\n" +
      "Three pointers do the job:\n" +
      "• `prev`: the head of the part already reversed (starts as `null`).\n" +
      "• `curr`: the node being flipped now (starts at the head).\n" +
      "• `next`: saved before the flip, because flipping `curr.next` destroys the only link to the rest of the list.\n\n" +
      "Each iteration: save `next`, point `curr.next` at `prev`, then move `prev` and `curr` one node forward. When `curr` is `null`, `prev` is the new head.",
    complexity: { time: 'O(n)', space: 'O(1)', verdict: 'Canonical' },
    pseudocode: [
      'prev = null, curr = head',
      'while curr !== null:',
      '  next = curr.next',
      '  curr.next = prev',
      '  prev = curr; curr = next',
      'return prev',
    ],
    example: { input: '1 → 2 → 3 → 4 → null', output: '4 → 3 → 2 → 1 → null' },
    steps: [
      { title: 'Start: prev = null, curr = 1. Nothing is reversed yet.', pseudoLine: 0,
        detail: 'Top panel: the reversed chain starting at prev. Bottom panel: the nodes still to visit, starting at curr.',
        linkedList: { nodes: [] },
        array: moveZerosFrame([1, 2, 3, 4], { 0: 'i' }, [[0, 'curr', 'red']]) },
      { title: 'curr=1: save next = 2, point 1.next at null, then prev = 1, curr = 2.', pseudoLine: 3,
        linkedList: { nodes: [{ value: 1, label: 'prev', highlight: 'new' }], tail: 'null' },
        array: moveZerosFrame([2, 3, 4], { 0: 'i' }, [[0, 'curr', 'red']]) },
      { title: 'curr=2: save next = 3, point 2.next at 1, then prev = 2, curr = 3.', pseudoLine: 3,
        linkedList: { nodes: [{ value: 2, label: 'prev', highlight: 'new' }, { value: 1 }], tail: 'null' },
        array: moveZerosFrame([3, 4], { 0: 'i' }, [[0, 'curr', 'red']]) },
      { title: 'curr=3: save next = 4, point 3.next at 2, then prev = 3, curr = 4.', pseudoLine: 3,
        linkedList: { nodes: [{ value: 3, label: 'prev', highlight: 'new' }, { value: 2 }, { value: 1 }], tail: 'null' },
        array: moveZerosFrame([4], { 0: 'i' }, [[0, 'curr', 'red']]) },
      { title: 'curr=4: save next = null, point 4.next at 3, then prev = 4, curr = null.', pseudoLine: 3,
        detail: 'Saving next first mattered here too: it is null, which is what ends the loop.',
        linkedList: { nodes: [{ value: 4, label: 'prev', highlight: 'new' }, { value: 3 }, { value: 2 }, { value: 1 }], tail: 'null' },
        array: moveZerosFrame(['null'], {}, [[0, 'curr', 'red']]) },
      { title: 'curr is null → the loop stops. Return prev (4) as the new head.', pseudoLine: 5,
        linkedList: { nodes: [{ value: 4, label: 'head', highlight: 'found' }, { value: 3 }, { value: 2 }, { value: 1 }], tail: 'null' },
        result: { found: true, value: '4 → 3 → 2 → 1 → null' } },
    ],
    tradeoffs: 'Recursive variant is elegant but uses O(n) call-stack — risky for very long lists. Iterative is the safe default. Reversing in groups of k is a follow-up question that uses the same three-pointer pattern within each group.',
  },
  {
    id: 'recursive',
    name: 'Recursive Reverse',
    badge: 'alternative',
    intuition:
      "**Reverse the rest of the list first, then attach the current node at its end.** Recurse until the last node, which is the new head, and fix one arrow on the way back up.\n\n" +
      "In the call for `head`, once `reverse(head.next)` returns:\n" +
      "• `head.next` is still the old second node, which is now the **tail** of the reversed rest.\n" +
      "• `head.next.next = head` hangs `head` after that tail.\n" +
      "• `head.next = null` cuts the old forward link, otherwise the two nodes would point at each other in a loop.\n" +
      "• Return `newHead` unchanged all the way up.\n\n" +
      "Recursion depth equals the list length, so a list of tens of thousands of nodes can overflow the call stack.",
    complexity: { time: 'O(n)', space: 'O(n) call stack', verdict: 'Elegant; risky for long lists' },
    pseudocode: [
      'function reverse(head):',
      '  if (head === null || head.next === null) return head',
      '  newHead = reverse(head.next)',
      '  head.next.next = head     // make next point back',
      '  head.next = null          // break original forward link',
      '  return newHead',
    ],
    example: { input: '1→2→3→null', output: '3→2→1→null' },
    steps: [
      { title: 'reverse(1): 1.next is 2, not the last node → call reverse(2).', pseudoLine: 2,
        callStack: { frames: [{ call: 'reverse(1)', status: 'active' }] },
        linkedList: { nodes: [{ value: 1, label: 'head', highlight: 'i' }, { value: 2 }, { value: 3 }], tail: 'null' } },
      { title: 'reverse(2): 2.next is 3 → call reverse(3).', pseudoLine: 2,
        callStack: { frames: [{ call: 'reverse(1)', status: 'pending' }, { call: 'reverse(2)', status: 'active' }] },
        linkedList: { nodes: [{ value: 1 }, { value: 2, label: 'head', highlight: 'i' }, { value: 3 }], tail: 'null' } },
      { title: 'reverse(3): 3.next is null → base case, return 3. It is the new head.', pseudoLine: 1,
        callStack: { frames: [{ call: 'reverse(1)', status: 'pending' }, { call: 'reverse(2)', status: 'pending' }, { call: 'reverse(3)', status: 'returned', returns: '3' }] },
        linkedList: { nodes: [{ value: 1 }, { value: 2 }, { value: 3, label: 'newHead', highlight: 'found' }], tail: 'null' } },
      { title: 'Back in reverse(2): 2.next.next = 2, so 3 now points back to 2.', pseudoLine: 3,
        detail: 'For a moment 2 → 3 and 3 → 2 form a loop. The next line breaks it.',
        callStack: { frames: [{ call: 'reverse(1)', status: 'pending' }, { call: 'reverse(2)', status: 'active' }] },
        linkedList: { nodes: [{ value: 3, label: 'newHead' }, { value: 2, highlight: 'i' }], tail: '3 (loop until the next line)' } },
      { title: 'reverse(2): 2.next = null. Reversed part is 3 → 2 → null. Return 3.', pseudoLine: 4,
        detail: 'Node 1 still points at 2. That is exactly what the caller relies on.',
        callStack: { frames: [{ call: 'reverse(1)', status: 'pending' }, { call: 'reverse(2)', status: 'returned', returns: '3' }] },
        linkedList: { nodes: [{ value: 3, label: 'newHead' }, { value: 2 }], tail: 'null' } },
      { title: 'Back in reverse(1): 1.next.next = 1, so 2 now points back to 1.', pseudoLine: 3,
        callStack: { frames: [{ call: 'reverse(1)', status: 'active' }] },
        linkedList: { nodes: [{ value: 3, label: 'newHead' }, { value: 2 }, { value: 1, highlight: 'i' }], tail: '2 (loop until the next line)' } },
      { title: 'reverse(1): 1.next = null. The list is 3 → 2 → 1 → null. Return 3.', pseudoLine: 5,
        callStack: { frames: [{ call: 'reverse(1)', status: 'returned', returns: '3' }] },
        linkedList: { nodes: [{ value: 3, label: 'head', highlight: 'found' }, { value: 2, highlight: 'found' }, { value: 1, highlight: 'found' }], tail: 'null' },
        result: { found: true, value: '3 → 2 → 1 → null' } },
    ],
    tradeoffs: '5 lines vs 7 for iterative. Same correctness, worse worst-case stack usage. Prefer iterative in production; mention recursive in interviews to show fluency.',
  }],
};

