// [3,1,4,4,5,5,2] with the current x marked.
const SECOND_LARGEST_ARR = [3, 1, 4, 4, 5, 5, 2];
const secondLargestFrame = (idx: number): ArraySnapshot =>
  moveZerosFrame(SECOND_LARGEST_ARR, { [idx]: 'i' }, [[idx, 'x', 'red']]);

const secondLargest: Explanation = {
  problem: 'Second Largest Number',
  problemStatement: 'Find the second-largest UNIQUE value in an array, without using sort.',
  approaches: [{
    id: 'single-pass',
    name: 'Single Pass — Two Variables',
    badge: 'best',
    intuition:
      "**Keep the top two distinct values seen so far, and update them as you scan.** Both start at `-Infinity`, which is smaller than any number.\n\n" +
      "For each `x`:\n" +
      "• `x > first`: a new maximum. The old maximum drops to second: `second = first; first = x`.\n" +
      "• Else if `x > second` and `x !== first`: a new runner-up → `second = x`.\n" +
      "• Otherwise: ignore it.\n\n" +
      "**The `x !== first` check is what makes the answer unique.** Without it, [5, 5] would report 5 as the second largest.",
    complexity: { time: 'O(n)', space: 'O(1)', verdict: 'Canonical' },
    pseudocode: [
      'first = -Infinity, second = -Infinity',
      'for x in arr:',
      '  if x > first: second = first; first = x',
      '  else if x > second && x !== first: second = x',
      'return second',
    ],
    example: { input: '[3, 1, 4, 4, 5, 5, 2]', output: '4' },
    steps: [
      { title: 'x=3: 3 > -∞ → new first. first = 3, second = -∞.', pseudoLine: 2,
        array: secondLargestFrame(0),
        computation: { label: 'first / second', result: '3 / -∞' } },
      { title: 'x=1: not > 3, but 1 > -∞ and 1 ≠ 3 → second = 1.', pseudoLine: 3,
        array: secondLargestFrame(1),
        computation: { label: 'first / second', result: '3 / 1' } },
      { title: 'x=4: 4 > 3 → the old first moves down. first = 4, second = 3.', pseudoLine: 2,
        array: secondLargestFrame(2),
        computation: { label: 'first / second', result: '4 / 3' } },
      { title: 'x=4: not > 4, and 4 === first → ignore.', pseudoLine: 3,
        detail: 'This is the duplicate case. Without the x !== first check, 4 > 3 would make second = 4.',
        array: secondLargestFrame(3),
        computation: { label: 'first / second', result: '4 / 3 (unchanged)' } },
      { title: 'x=5: 5 > 4 → first = 5, second = 4.', pseudoLine: 2,
        array: secondLargestFrame(4),
        computation: { label: 'first / second', result: '5 / 4' } },
      { title: 'x=5: equals first → ignore.', pseudoLine: 3,
        array: secondLargestFrame(5),
        computation: { label: 'first / second', result: '5 / 4 (unchanged)' } },
      { title: 'x=2: not > 5, and 2 is not > 4 → ignore.', pseudoLine: 3,
        array: secondLargestFrame(6),
        computation: { label: 'first / second', result: '5 / 4 (unchanged)' } },
      { title: 'The scan is done → return second = 4.', pseudoLine: 4,
        array: moveZerosFrame(SECOND_LARGEST_ARR, { 2: 'found', 3: 'found' }),
        result: { found: true, value: '4' } },
    ],
    tradeoffs: 'Two-pass version (find max, then max of rest) is fine — same complexity, easier to read, but two scans. Set + sort is O(n log n). Heap is overkill at k=2 but generalizes to "k-th largest" in O(n log k).',
  },
  {
    id: 'set-sort',
    name: 'Set + Sort (Most Readable)',
    badge: 'alternative',
    intuition:
      "**Remove duplicates, sort biggest first, take index 1.** It reads like the problem statement: unique values, largest first, the second one.\n\n" +
      "• `[...new Set(arr)]`: a `Set` keeps one copy of each value; spreading it gives an array back.\n" +
      "• `sort((a, b) => b - a)`: a negative result puts `a` first, so larger values come first. Without a comparator, `sort` compares as strings and would put 10 before 9.\n" +
      "• Fewer than 2 unique values means there is no second largest → `null`.\n\n" +
      "**Trade:** O(n log n) for the sort instead of O(n), in exchange for three obvious lines.",
    complexity: { time: 'O(n log n)', space: 'O(n)', verdict: 'Pick this when readability matters more than the optimal complexity' },
    pseudocode: [
      'unique = [...new Set(arr)]',
      'unique.sort((a, b) => b - a)         // descending',
      'return unique.length >= 2 ? unique[1] : null',
    ],
    example: { input: '[3, 1, 4, 4, 5, 5, 2]', output: '4' },
    steps: [
      { title: 'new Set drops the repeated 4 and 5 → [3, 1, 4, 5, 2].', pseudoLine: 0,
        detail: 'A Set keeps the first occurrence of each value, in insertion order.',
        set: { items: [{ value: 3 }, { value: 1 }, { value: 4 }, { value: 5 }, { value: 2 }] },
        array: moveZerosFrame([3, 1, 4, 5, 2]) },
      { title: 'Sort descending → [5, 4, 3, 2, 1].', pseudoLine: 1,
        array: moveZerosFrame([5, 4, 3, 2, 1], { 0: 'compare' }) },
      { title: '5 unique values ≥ 2 → return unique[1] = 4.', pseudoLine: 2,
        array: moveZerosFrame([5, 4, 3, 2, 1], { 1: 'found' }, [[1, '[1]', 'emerald']]),
        result: { found: true, value: '4' } },
    ],
    tradeoffs: 'Three readable lines for the price of O(n log n). Use unless n is huge or someone explicitly says "must be O(n)".',
    usesPolyfills: [
      { builtin: 'Array.prototype.sort', templateName: 'Array.sort',
        why: 'sort the deduped values descending to pick index 1' },
    ],
  }],
};

