// ==================== Template Explanations: JS Interview Topics ====================

// One event-loop frame: what is running, both queues, and the console so far.
const eventLoopMicrotasksFrame = (running: string, micro: string[], macro: string[], out: string[]): Pick<ExplanationStep, 'callStack' | 'dualArray'> => ({
  callStack: { frames: running ? [{ call: running, status: 'active' as const }] : [] },
  dualArray: {
    left: { label: 'Microtask queue (drained completely)', cells: micro.map(v => ({ value: v })) },
    right: { label: 'Macrotask queue (one per turn)', cells: macro.map(v => ({ value: v })) },
    result: { label: 'Console output', cells: out.map((v, i) => ({ value: v, highlight: i === out.length - 1 ? 'new' as const : undefined })) },
  },
});

const eventLoopMicrotasks: Explanation = {
  problem: 'Event Loop & Microtasks',
  problemStatement: 'JavaScript is single-threaded. The event loop is what lets it handle async work without blocking.',
  approaches: [{
    id: 'queue-model',
    name: 'Call Stack + Microtask + Macrotask Queues',
    badge: 'best',
    intuition:
      "**The event loop runs one task to completion, then empties the microtask queue, then takes the next task.** That one rule predicts every \"what order does this print?\" question.\n\n" +
      "**Three places code waits:**\n" +
      "• The **call stack**: the functions running right now. Your whole script is the first task.\n" +
      "• The **microtask queue**: callbacks from `.then`/`await` and `queueMicrotask`. It is drained completely every time the call stack empties, including microtasks that other microtasks queue.\n" +
      "• The **macrotask queue** (also called the task queue): `setTimeout`, `setInterval`, I/O and UI events. The loop takes one per turn, and a browser may paint between turns.\n\n" +
      "**The non-obvious part:** `setTimeout(fn, 0)` does not mean \"run next\". It means \"queue fn as a macrotask after at least 0 ms\". Every microtask already queued runs first, so 3 and 4 print before 2 even though the timeout was scheduled earlier.\n\n" +
      "**Watch out:** because the drain is complete, a microtask that keeps queuing another microtask never lets a timer or a paint through, and the page freezes.\n\n" +
      "The walkthrough traces the template's code one statement, then one queued callback, at a time.",
    complexity: { time: 'Each task O(its work)', space: 'O(queued tasks)', verdict: 'Core mental model' },
    pseudocode: [
      'console.log("1: sync");',
      'setTimeout(() => console.log("2: setTimeout (macro)"), 0);',
      'Promise.resolve().then(() => console.log("3: Promise (micro)"));',
      'queueMicrotask(() => console.log("4: queueMicrotask (micro)"));',
      'console.log("5: sync");',
      '// Output: 1, 5, 3, 4, 2',
    ],
    example: { input: 'the template: two sync logs, one setTimeout, two microtasks', output: '1, 5, 3, 4, 2' },
    steps: [
      { title: 'The script is the first task. Line 1 runs on the call stack and logs 1.', pseudoLine: 0,
        detail: 'Synchronous code always finishes before any queued callback gets a turn.',
        ...eventLoopMicrotasksFrame('script (line 1)', [], [], ['1']) },
      { title: 'setTimeout(cb, 0) does not run its callback. The timer puts it in the macrotask queue.', pseudoLine: 1,
        detail: 'After the 0 ms delay the callback becomes a macrotask. It still has to wait for the script to end and for every microtask.',
        ...eventLoopMicrotasksFrame('script (line 2)', [], ['log2'], ['1']) },
      { title: 'Promise.resolve() is already fulfilled, so .then queues its callback as a microtask right away.', pseudoLine: 2,
        ...eventLoopMicrotasksFrame('script (line 3)', ['log3'], ['log2'], ['1']) },
      { title: 'queueMicrotask adds a second microtask behind the first.', pseudoLine: 3,
        detail: 'Both queues are first-in, first-out, so 3 will run before 4.',
        ...eventLoopMicrotasksFrame('script (line 4)', ['log3', 'log4'], ['log2'], ['1']) },
      { title: 'Line 5 is synchronous: log 5. The script ends and the call stack is empty.', pseudoLine: 4,
        ...eventLoopMicrotasksFrame('script (line 5)', ['log3', 'log4'], ['log2'], ['1', '5']) },
      { title: 'Stack empty → drain microtasks. Run the first one: log 3.', pseudoLine: 2,
        detail: 'Microtasks go before macrotasks, so the timeout keeps waiting even though it was queued first.',
        ...eventLoopMicrotasksFrame('microtask: log 3', ['log4'], ['log2'], ['1', '5', '3']) },
      { title: 'The microtask queue is not empty yet, so keep draining: log 4.', pseudoLine: 3,
        detail: 'The loop does not move on after one microtask. It empties the whole queue.',
        ...eventLoopMicrotasksFrame('microtask: log 4', [], ['log2'], ['1', '5', '3', '4']) },
      { title: 'Microtasks empty → take one macrotask: the timeout callback logs 2.', pseudoLine: 1,
        detail: 'In a browser this is also where a paint can happen, between the microtask drain and the next macrotask.',
        ...eventLoopMicrotasksFrame('macrotask: log 2', [], [], ['1', '5', '3', '4', '2']),
        result: { found: true, value: '1, 5, 3, 4, 2' } },
    ],
    tradeoffs: 'requestAnimationFrame runs BEFORE the next render — between macrotasks but separate from the microtask queue. Use rAF for visual changes; microtasks for "do this right after the current sync chunk".',
  }],
};

const thisKeyword: Explanation = {
  problem: 'this Keyword',
  problemStatement: '`this` is the implicit context of a function call. Its value is determined by HOW the function is called, not where it was defined.',
  approaches: [{
    id: 'four-rules',
    name: 'Four Binding Rules + Arrow Exception',
    badge: 'best',
    intuition:
      "**Look at the call site, not the definition.** The same function gets a different `this` depending on how the line that calls it is written.\n\n" +
      "**Four rules, strongest first:**\n" +
      "1. **`new` binding:** `new Fn()` makes `this` a brand-new object.\n" +
      "2. **Explicit binding:** `fn.call(ctx)`, `fn.apply(ctx)`, `fn.bind(ctx)` set `this` to `ctx`. A function made by `bind` keeps that `this` for good, even if you later `.call` it with something else.\n" +
      "3. **Implicit binding:** `obj.fn()` makes `this` the object before the dot.\n" +
      "4. **Default binding:** a plain `fn()` gets the global object in sloppy mode (the old, non-strict mode of JavaScript) and `undefined` in strict mode or an ES module.\n\n" +
      "**Arrow functions are the exception:** they have no `this` of their own. They use the `this` of the code around the place they were written, so none of the four rules change it.\n\n" +
      "**Why the playground output looks odd:** it runs your code as a sloppy script inside a Web Worker. There the global object is the worker's own global, and its `name` property is an empty string. So a detached `greet()` prints \"Hi, I'm \" with nothing after it, where a module would throw a TypeError instead.",
    complexity: { time: 'O(1)', space: 'O(1)', verdict: 'Core JS concept' },
    pseudocode: [
      'const obj = {',
      '  name: "Alice",',
      "  greet() { return `Hi, I'm ${this.name}`; },",
      "  greetArrow: () => `Hi, I'm ${typeof this?.name}`,",
      '};',
      'obj.greet();                    // implicit',
      'obj.greetArrow();               // arrow: no own this',
      'const greet = obj.greet;        // copy the function out',
      'greet();                        // default: detached',
      'greet.call({ name: "Bob" });    // explicit, one call',
      'greet.bind({ name: "Eve" })();  // explicit, permanent',
      'function User(n) { this.name = n; }',
      'new User("Ann").name;           // new',
    ],
    example: { input: 'the template\'s five calls, plus one call with new', output: '"Hi, I\'m Alice", "Hi, I\'m string", "Hi, I\'m " (TypeError in strict mode), "Hi, I\'m Bob", "Hi, I\'m Eve", "Ann"' },
    steps: [
      { title: 'obj.greet(): there is an object before the dot → this = obj → "Hi, I\'m Alice".', pseudoLine: 5,
        detail: 'Rule 3, implicit binding. The dot at the call site is what supplies `this`.',
        computation: { label: 'which rule?', lhs: 'obj.greet()', op: '→', rhs: 'obj before the dot', result: 'this = obj' },
        map: { entries: [{ key: 'this', value: 'obj', highlight: 'hit' }, { key: 'returns', value: '"Hi, I\'m Alice"', highlight: 'new' }] } },
      { title: 'obj.greetArrow(): an arrow ignores the dot and uses the outer this → "Hi, I\'m string".', pseudoLine: 6,
        detail: 'The arrow was written at the top level of the script, so it uses the top-level `this`. In the playground that is the worker\'s global object, whose name is "" (a string). In an ES module the top-level `this` is undefined, and you would see "Hi, I\'m undefined".',
        computation: { label: 'which rule?', lhs: 'obj.greetArrow()', op: '→', rhs: 'arrow: no own this', result: 'top-level this' },
        map: { entries: [{ key: 'this', value: 'worker global', highlight: 'hit' }, { key: 'typeof this.name', value: '"string"' }, { key: 'returns', value: '"Hi, I\'m string"', highlight: 'new' }] } },
      { title: 'const greet = obj.greet copies the function only. No this travels with it.', pseudoLine: 7,
        detail: 'A method is an ordinary function stored in a property. Reading it out gives you the bare function.',
        map: { entries: [{ key: 'greet', value: 'function greet()', highlight: 'new' }, { key: 'this', value: 'decided at the next call' }] } },
      { title: 'greet(): no dot, no call/bind, no new → default binding → "Hi, I\'m " (empty name).', pseudoLine: 8,
        detail: 'In sloppy mode `this` falls back to the global object, and the worker\'s global has name "". With "use strict" or in a module, `this` is undefined and `this.name` throws TypeError: Cannot read properties of undefined (reading \'name\'). The template\'s try/catch is there for that case.',
        computation: { label: 'which rule?', lhs: 'greet()', op: '→', rhs: 'nothing at the call site', result: 'global (sloppy) / undefined (strict)' },
        map: { entries: [{ key: 'this (sloppy)', value: 'worker global, name ""', highlight: 'hit' }, { key: 'this (strict)', value: 'undefined → TypeError' }, { key: 'returns', value: '"Hi, I\'m "', highlight: 'new' }] },
        note: 'This is the classic React class bug: passing this.handleClick as a prop detaches it the same way.' },
      { title: 'greet.call({ name: "Bob" }): explicit binding for this one call → "Hi, I\'m Bob".', pseudoLine: 9,
        computation: { label: 'which rule?', lhs: 'greet.call(ctx)', op: '→', rhs: 'explicit', result: 'this = { name: "Bob" }' },
        map: { entries: [{ key: 'this', value: '{ name: "Bob" }', highlight: 'hit' }, { key: 'returns', value: '"Hi, I\'m Bob"', highlight: 'new' }] } },
      { title: 'greet.bind({ name: "Eve" })(): bind returns a new function with this fixed → "Hi, I\'m Eve".', pseudoLine: 10,
        detail: 'The binding is permanent: calling that bound function with .call({ name: "Bob" }) still prints "Hi, I\'m Eve".',
        computation: { label: 'which rule?', lhs: 'bound()', op: '→', rhs: 'explicit (bind)', result: 'this = { name: "Eve" }' },
        map: { entries: [{ key: 'this', value: '{ name: "Eve" }', highlight: 'hit' }, { key: 'returns', value: '"Hi, I\'m Eve"', highlight: 'new' }] } },
      { title: 'new User("Ann"): new makes a fresh object, runs User with this = that object, and returns it → .name is "Ann".', pseudoLine: 12,
        detail: 'Rule 1 beats all the others. The template does not use new, so this line is added to cover the fourth rule.',
        computation: { label: 'which rule?', lhs: 'new User("Ann")', op: '→', rhs: 'new', result: 'this = fresh object' },
        map: { entries: [{ key: 'this', value: '{ name: "Ann" }', highlight: 'hit' }, { key: 'returns', value: '"Ann"', highlight: 'new' }] },
        result: { found: true, value: 'new > call/apply/bind > obj.fn() > plain fn(); arrows use the outer this' } },
    ],
    tradeoffs: 'In class fields, `method = () => { ... }` creates an arrow bound to the instance — pre-bound, no .bind needed, but uses more memory (one closure per instance) versus prototype methods (one shared method).',
  }],
};

// Calls a..e arrive every 50 ms. `upTo` = how many have arrived so far.
const debounceThrottleTemplateInputs = (upTo: number): TimelineSnapshot['events'] =>
  ['a', 'b', 'c', 'd', 'e'].slice(0, upTo).map((label, i) => ({ t: i * 50, label, kind: 'input' as const }));

// Throttle view: each arrived call is drawn as fired or skipped.
const debounceThrottleTemplateThrottle = (upTo: number): TimelineSnapshot => ({
  events: ['a', 'b', 'c', 'd', 'e'].slice(0, upTo).map((label, i) => ({
    t: i * 50,
    label: i === 0 || i === 4 ? 'fn(' + label + ')' : label + ' ✕',
    kind: i === 0 || i === 4 ? 'fire' as const : 'skip' as const,
  })),
  windowMs: 200,
});

const debounceThrottleTemplate: Explanation = {
  problem: 'Debounce & Throttle',
  problemStatement: 'Two rate-limiting patterns. Debounce: fire only after a quiet period. Throttle: fire at most once per window.',
  approaches: [{
    id: 'difference',
    name: 'The Key Difference',
    badge: 'best',
    intuition:
      "**Debounce waits for silence. Throttle keeps a steady pace.** Both wrap a function and decide, call by call, whether it runs.\n\n" +
      "**Debounce:** every call cancels the pending timer and starts a new one. The function runs only once `wait` ms pass with no new call, using the LAST call's arguments. Use it for search-as-you-type and resize handlers.\n\n" +
      "**Throttle:** the function runs at most once per `wait` ms. This version is leading-edge, meaning the first call in a window runs immediately and the calls after it in that window are dropped. Use it for scroll tracking and rate-limited buttons.\n\n" +
      "**The mechanism both rely on:** a closure, meaning the returned function keeps access to the variables of the function that created it. Here that is `timer` (debounce) and `last` (throttle), which survive from one call to the next.\n\n" +
      "The walkthrough feeds both the same five calls, a to e, 50 ms apart, with wait = 200 ms.",
    complexity: { time: 'O(1) per call', space: 'O(1)', verdict: 'Both are everyday tools' },
    pseudocode: [
      'function debounce(fn, wait) {',
      '  let timer;',
      '  return (...args) => {',
      '    clearTimeout(timer);',
      '    timer = setTimeout(() => fn(...args), wait);',
      '  };',
      '}',
      '',
      'function throttle(fn, wait) {',
      '  let last = 0;',
      '  return (...args) => {',
      '    if (Date.now() - last >= wait) {',
      '      last = Date.now();',
      '      fn(...args);',
      '    }',
      '  };',
      '}',
    ],
    example: { input: 'calls a, b, c, d, e at t = 0, 50, 100, 150, 200 ms; wait = 200 ms', output: 'debounce: fn("e") once, at 400 ms. throttle: fn("a") at 0 ms and fn("e") at 200 ms' },
    steps: [
      { title: 'Debounce, t=0: call a. No timer yet, so schedule fn("a") for t=200.', pseudoLine: 4,
        detail: 'clearTimeout(undefined) is harmless, so the first call needs no special case.',
        timeline: { events: [...debounceThrottleTemplateInputs(1), { t: 200, label: 'a @200?', kind: 'pending' }], windowMs: 200 } },
      { title: 'Debounce, t=50: call b. Cancel the a timer, schedule fn("b") for t=250.', pseudoLine: 3,
        timeline: { events: [...debounceThrottleTemplateInputs(2), { t: 200, label: 'a ✕', kind: 'skip' }, { t: 250, label: 'b @250?', kind: 'pending' }], windowMs: 200 } },
      { title: 'Debounce, t=100: call c. Cancel the b timer, schedule fn("c") for t=300.', pseudoLine: 3,
        timeline: { events: [...debounceThrottleTemplateInputs(3), { t: 250, label: 'b ✕', kind: 'skip' }, { t: 300, label: 'c @300?', kind: 'pending' }], windowMs: 200 } },
      { title: 'Debounce, t=150: call d. Cancel the c timer, schedule fn("d") for t=350.', pseudoLine: 3,
        timeline: { events: [...debounceThrottleTemplateInputs(4), { t: 300, label: 'c ✕', kind: 'skip' }, { t: 350, label: 'd @350?', kind: 'pending' }], windowMs: 200 } },
      { title: 'Debounce, t=200: call e. Cancel the d timer, schedule fn("e") for t=400.', pseudoLine: 3,
        detail: 'Each call pushes the deadline back. As long as calls keep coming faster than every 200 ms, nothing runs.',
        timeline: { events: [...debounceThrottleTemplateInputs(5), { t: 350, label: 'd ✕', kind: 'skip' }, { t: 400, label: 'e @400?', kind: 'pending' }], windowMs: 200 } },
      { title: 'Debounce, t=400: 200 ms of silence. The timer fires fn("e"), once.', pseudoLine: 4,
        detail: 'Only the last call\'s arguments survive, because every earlier timer was cleared.',
        timeline: { events: [...debounceThrottleTemplateInputs(5), { t: 400, label: 'fn(e)', kind: 'fire' }], windowMs: 200 },
        result: { found: true, value: 'debounce: 5 calls → 1 run, fn("e") at 400 ms' } },
      { title: 'Throttle, t=0: call a. last is 0, so Date.now() − last is huge → run fn("a"), set last = 0 ms.', pseudoLine: 13,
        detail: 'last starts at 0, and Date.now() counts milliseconds since 1970, so the very first call always passes the check.',
        timeline: debounceThrottleTemplateThrottle(1),
        computation: { label: 'Date.now() − last', lhs: 'huge ≥ 200', result: 'true → run, last = 0 ms' } },
      { title: 'Throttle, t=50: call b. 50 − 0 = 50 < 200 → drop it.', pseudoLine: 11,
        timeline: debounceThrottleTemplateThrottle(2),
        computation: { label: 'Date.now() − last', lhs: '50 − 0 = 50', op: '≥ 200?', result: 'false → drop b' } },
      { title: 'Throttle, t=100: call c. 100 − 0 = 100 < 200 → drop it.', pseudoLine: 11,
        timeline: debounceThrottleTemplateThrottle(3),
        computation: { label: 'Date.now() − last', lhs: '100 − 0 = 100', op: '≥ 200?', result: 'false → drop c' } },
      { title: 'Throttle, t=150: call d. 150 − 0 = 150 < 200 → drop it.', pseudoLine: 11,
        timeline: debounceThrottleTemplateThrottle(4),
        computation: { label: 'Date.now() − last', lhs: '150 − 0 = 150', op: '≥ 200?', result: 'false → drop d' } },
      { title: 'Throttle, t=200: call e. 200 − 0 = 200 ≥ 200 → run fn("e"), set last = 200.', pseudoLine: 13,
        detail: 'Throttle ran twice at a steady pace while the calls were still coming. Debounce ran once, only after they stopped.',
        timeline: debounceThrottleTemplateThrottle(5),
        computation: { label: 'Date.now() − last', lhs: '200 − 0 = 200', op: '≥ 200?', result: 'true → run, last = 200' },
        result: { found: true, value: 'throttle: 5 calls → 2 runs, fn("a") at 0 ms and fn("e") at 200 ms' } },
    ],
    tradeoffs: 'Most production libraries (lodash) offer both leading + trailing variants of each. Debounce defaults trailing; throttle defaults leading. Real-world: search uses debounce (trailing), scroll uses throttle (leading).',
  }],
};

// The arguments collected so far, drawn as cells (arity 3, so three slots).
const curryingTemplateArgs = (args: number[], fresh: number[] = []): ArraySnapshot => ({
  cells: [0, 1, 2].map(i => i < args.length
    ? { value: args[i], highlight: fresh.includes(i) ? 'new' as const : undefined }
    : { value: '_' }),
});

const curryingTemplate: Explanation = {
  problem: 'Currying',
  problemStatement: 'Transform a multi-argument function into a chain of single-argument functions: `f(a, b, c)` becomes `f(a)(b)(c)`.',
  approaches: [{
    id: 'closure-chain',
    name: 'Closure-Chain Currying',
    badge: 'best',
    intuition:
      "**Keep collecting arguments until there are enough, then call the real function.** `curry(add)` returns a function that remembers what it has been given so far.\n\n" +
      "**The one decision, made on every call:**\n" +
      "• `args.length >= fn.length`: enough arguments. Call `fn(...args)` and return its result.\n" +
      "• Otherwise: return a new function. When that one is called, it joins the old arguments with the new ones and makes the same decision again.\n\n" +
      "`fn.length` is the function's arity, meaning how many parameters it declares. `(a, b, c) => ...` has length 3.\n\n" +
      "**The mechanism:** each returned function is a closure, meaning it keeps access to the `args` array that existed when it was created. That is how `1` is still there two calls later.\n\n" +
      "**Why it matters:** `const addFive = add(5)` makes a specialised function from a general one, which is handy with `map` and composition.\n\n" +
      "**The gotcha:** `fn.length` stops counting at the first default or rest parameter. `((a, b = 2) => a + b).length` is 1 and `((...xs) => 0).length` is 0, so curry would call those too early.",
    complexity: { time: 'O(1) per call; O(n) closures in chain', space: 'O(n)', verdict: 'Pattern, not algorithm' },
    pseudocode: [
      'function curry(fn) {',
      '  return function curried(...args) {',
      '    if (args.length >= fn.length) return fn(...args);',
      '    return (...next) => curried(...args, ...next);',
      '  };',
      '}',
      '',
      'const add = (a, b, c) => a + b + c;',
      'const cAdd = curry(add);',
      'cAdd(1)(2)(3);      // 6',
      'cAdd(1, 2)(3);      // 6',
      'cAdd(1)(2, 3);      // 6',
    ],
    example: { input: 'curry(add)(1)(2)(3), then curry(add)(1, 2)(3)', output: '6 and 6' },
    steps: [
      { title: 'curry(add) returns curried. It remembers fn = add, whose fn.length is 3.', pseudoLine: 8,
        detail: 'Nothing has been added yet. cAdd is just the first collector.',
        callStack: { frames: [{ call: 'curry(add)', status: 'returned', returns: 'curried' }] },
        array: curryingTemplateArgs([]) },
      { title: 'cAdd(1) → curried(1): args = [1]. 1 >= 3 is false → return a collector holding [1].', pseudoLine: 3,
        callStack: { frames: [{ call: 'curried(1)', status: 'returned', returns: '(...next) => curried(1, ...next)' }] },
        array: curryingTemplateArgs([1], [0]),
        computation: { label: 'args.length >= fn.length', lhs: '1 >= 3', result: 'false → return a collector' } },
      { title: '(2) → curried(1, 2): args = [1, 2]. 2 >= 3 is false → return another collector.', pseudoLine: 3,
        detail: 'The collector spreads its remembered [1] in front of the new 2, then asks curried to decide again.',
        callStack: { frames: [{ call: 'collector(2)', status: 'pending' }, { call: 'curried(1, 2)', status: 'returned', returns: '(...next) => curried(1, 2, ...next)' }] },
        array: curryingTemplateArgs([1, 2], [1]),
        computation: { label: 'args.length >= fn.length', lhs: '2 >= 3', result: 'false → return a collector' } },
      { title: '(3) → curried(1, 2, 3): 3 >= 3 is true → call add(1, 2, 3) → 6.', pseudoLine: 2,
        callStack: { frames: [{ call: 'collector(3)', status: 'pending' }, { call: 'curried(1, 2, 3)', status: 'pending' }, { call: 'add(1, 2, 3)', status: 'returned', returns: '6' }] },
        array: curryingTemplateArgs([1, 2, 3], [2]),
        computation: { label: 'args.length >= fn.length', lhs: '3 >= 3', result: 'true → add(1, 2, 3) = 6' },
        result: { found: true, value: 'cAdd(1)(2)(3) = 6' } },
      { title: 'cAdd(1, 2) → curried(1, 2): two arguments arrive at once. 2 >= 3 is false → return a collector.', pseudoLine: 10,
        detail: 'Nothing forces one argument per call. Each call can bring any number, and the length check is the same.',
        callStack: { frames: [{ call: 'curried(1, 2)', status: 'returned', returns: '(...next) => curried(1, 2, ...next)' }] },
        array: curryingTemplateArgs([1, 2], [0, 1]),
        computation: { label: 'args.length >= fn.length', lhs: '2 >= 3', result: 'false → return a collector' } },
      { title: '(3) → curried(1, 2, 3): 3 >= 3 is true → add(1, 2, 3) → 6.', pseudoLine: 2,
        callStack: { frames: [{ call: 'collector(3)', status: 'pending' }, { call: 'curried(1, 2, 3)', status: 'pending' }, { call: 'add(1, 2, 3)', status: 'returned', returns: '6' }] },
        array: curryingTemplateArgs([1, 2, 3], [2]),
        computation: { label: 'args.length >= fn.length', lhs: '3 >= 3', result: 'true → add(1, 2, 3) = 6' },
        result: { found: true, value: 'cAdd(1, 2)(3) = 6' } },
    ],
    tradeoffs: 'Auto-curry (lodash/curry) handles arbitrary arity and supports placeholders. The hand-rolled version is simpler but assumes you know fn.length. Ramda goes further and curries every function by default.',
  }],
};

